local config = {
  ui_story_5086_50860100_1_dialog_content = "... PlayerName, Elvis... I...",
  ui_story_5086_50860100_2_dialog_content = "Huh... Jeno?",
  ui_story_5086_50860100_3_dialog_content = "What did you say? I can't hear you...",
  ui_story_5086_50860100_4_dialog_content = "I felt a moment in which a miraculous tide rose.",
  ui_story_5086_50860100_5_dialog_content = "The time has come for me to pursue a crucial juncture determined by fate.",
  ui_story_5086_50860100_6_dialog_content = "So please...",
  ui_story_5086_50860100_7_dialog_content = "Wait, Jeno!",
  ui_story_5086_50860100_8_dialog_content = "... Was I dreaming just now?",
  ui_story_5086_50860100_9_dialog_content = "What a strange and unclear dream.",
  ui_story_5086_50860100_10_dialog_content = "I wonder if it's because of that letter I got yesterday?",
  ui_story_5086_50860100_11_dialog_content = "<color=#e8d9bb>\"My apologies for sending such an urgent letter. I left a message for you in Harbor City. Please come alone to receive it. —Jeno\"</color>",
  ui_story_5086_50860100_12_dialog_content = "His letter is also strange and unclear... but it sounds like he's being serious.",
  ui_story_5086_50860100_13_dialog_content = "He specifically asked me to come alone... Does this mean he doesn't want me to bring Vice or Carleen? I wonder what it could be...",
  ui_story_5086_50860100_14_dialog_content = "<color=#e8d9bb>The sea breeze blows softly as the streets of the normally-peaceful city bustle with crowds of tourists.</color>",
  ui_story_5086_50860100_15_dialog_content = "It doesn't feel like that much time has passed, but it looks like Harbor City has finally recovered from that crisis.",
  ui_story_5086_50860100_16_dialog_content = "If only Elvis were here to see it, I'm sure he'd be so proud... Huh?",
  ui_story_5086_50860100_17_dialog_content = "That's odd... The Emerald was docked right here, wasn't it?",
  ui_story_5086_50860100_18_dialog_content = "How could such a huge ship go missing?",
  ui_story_5086_50860100_19_dialog_content = "You here to see the performances, pal?",
  ui_story_5086_50860100_20_dialog_content = "Hate to break it to you, but you missed your chance. The circus raised anchor and took off a few days ago.",
  ui_story_5086_50860100_21_dialog_content = "Took off? But why?",
  ui_story_5086_50860100_22_dialog_content = "Dunno, but I heard it had something to do with someone who got hurt in the chaos before.",
  ui_story_5086_50860100_23_dialog_content = "No, no, you got it all wrong!",
  ui_story_5086_50860100_24_dialog_content = "Everyone knows that the ringmaster got into a huge fight with his lover, so he set sail to go find them!",
  ui_story_5086_50860100_25_dialog_content = "What? I thought it was because a wondrous beast escaped from the ship!",
  ui_story_5086_50860100_26_dialog_content = "You all saw it, didn't you? That huge whale was leading the way!",
  ui_story_5086_50860100_27_dialog_content = "Well, they did leave in a hurry... That much is certain.",
  ui_story_5086_50860100_28_dialog_content = "I just hope nothing bad happened.",
  ui_story_5086_50860100_29_dialog_content = "So where am I supposed to find Jeno now?",
  ui_story_5086_50860100_30_dialog_content = "The letter didn't say... Hang on, there's an address written on the back! Guess I didn't notice it earlier.",
  ui_story_5086_50860100_31_dialog_content = "130 Coral Street—",
  ui_story_5086_50860100_32_dialog_content = "Welcome to Harbor City's undersea wonderland, a place where dreams and the sea meet!",
  ui_story_5086_50860100_33_dialog_content = "Would you like to swim with sharks?",
  ui_story_5086_50860100_34_dialog_content = "Or maybe kick back and relax with a sea turtle?",
  ui_story_5086_50860100_35_dialog_content = "You can even join those jellyfish and blow beautiful bubbles!",
  ui_story_5086_50860100_36_dialog_content = "Anything is possible in this fantastic place!",
  ui_story_5086_50860100_37_dialog_content = "... An aquarium?",
  ui_story_5086_50860100_38_dialog_content = "That's right, an aquarium!",
  ui_story_5086_50860100_39_dialog_content = "We have all kinds of adorable marine creatures that are sure to capture your heart! Is this your first time here?",
  ui_story_5086_50860100_40_dialog_content = "If so, may I suggest starting from the left side of the first floor...",
  ui_story_5086_50860100_41_dialog_content = "Er... What was on display over there again? Sorry, I have such an awful short-term memory. Let me just check my notes...",
  ui_story_5086_50860100_42_dialog_content = "Uh, I'm not here to—",
  ui_story_5086_50860100_43_dialog_content = "Aha, there it is! It's the coral reef exhibit!",
  ui_story_5086_50860100_44_dialog_content = "We're also hosting an interactive event today! Guests can touch some starfish there, while children ten and under are free!",
  ui_story_5086_50860100_45_dialog_content = "I definitely look older than ten years old, don't you think?",
  ui_story_5086_50860100_46_dialog_content = "Hmm... I suppose so.",
  ui_story_5086_50860100_47_dialog_content = "Let's try this instead!",
  ui_story_5086_50860100_48_dialog_content = "<color=#e8d9bb>The young girl suddenly covers her right eye with her hand.</color>",
  ui_story_5086_50860100_49_dialog_content = "Since I can only see half of you, that means I have to consider you as being half your normal age!",
  ui_story_5086_50860100_50_dialog_content = "Great, now you can get in for free!",
  ui_story_5086_50860100_51_dialog_content = "I'm sorry, Miss... Maya, is it? I appreciate the thought, but I came here on some pretty serious business. If you'll excuse me—",
  ui_story_5086_50860100_52_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5086_50860100_53_dialog_content = "Ah! I-I'm so sorry!",
  ui_story_5086_50860100_54_dialog_content = "That voice...",
  ui_story_5086_50860100_55_dialog_content = "Pardon the interruption, miss, but my companion has accidentally knocked over your display sign at the entrance.",
  ui_story_5086_50860100_56_dialog_content = "Please allow us to fully compensate you for the damages.",
  ui_story_5086_50860100_57_dialog_content = "That's okay, I just doodled that sign myself. I'm just happy neither of you are hurt.",
  ui_story_5086_50860100_58_dialog_content = "I'm really, truly sorry about this...",
  ui_story_5086_50860100_59_dialog_content = "Minos! Sanae! It really is you two!",
  ui_story_5086_50860100_60_dialog_content = "Mr. PlayerName! I didn't expect to see you here... Ah! I'm sorry, that's no way to greet a friend!",
  ui_story_5086_50860100_61_dialog_content = "Um, h-how have you been...",
  ui_story_5086_50860100_62_dialog_content = "I've been well, Sanae. It's good to see you and Minos again.",
  ui_story_5086_50860100_63_dialog_content = "Good day, Mr. PlayerName. Glad to see you've been doing well after all this time.",
  ui_story_5086_50860100_64_dialog_content = "Isn't Nina with you guys?",
  ui_story_5086_50860100_65_dialog_content = "I'm afraid not... Miss Nina is currently busy with a new design... so she asked me to... conduct an industry investigation in her place.",
  ui_story_5086_50860100_66_dialog_content = "Indeed. I, on the other hand, am here to assist in the matter.",
  ui_story_5086_50860100_67_dialog_content = "... Are you sure you're not getting your roles mixed up?",
  ui_story_5086_50860100_68_dialog_content = "Fret not, sir. Though Sanae still has much to learn as a maid—",
  ui_story_5086_50860100_69_dialog_content = "As someone of the same age as our young lady, she happens to share a number of her noble sensibilities as well.",
  ui_story_5086_50860100_70_dialog_content = "Most important, however, is the fact that Miss Nina was willing to place her trust in her.",
  ui_story_5086_50860100_71_dialog_content = "So long as she continues to live up to our lady's expectations, I have no reason to interfere in her duties.",
  ui_story_5086_50860100_72_dialog_content = "My lady wishes to involve herself in this industry, but as a butler of the Andersen family, if I should discover that there are far too many unstable factors at play...",
  ui_story_5086_50860100_73_dialog_content = "The look in your eyes is suddenly a lot more terrifying, Minos.",
  ui_story_5086_50860100_74_dialog_content = "Is that so? Then please forgive my rudeness. I simply meant that I would take corrective action if that were the case.",
  ui_story_5086_50860100_75_dialog_content = "<color=#e8d9bb>Suddenly, a loud commotion can be heard just outside the door—</color>",
  ui_story_5086_50860100_76_dialog_content = "What's going on out there?",
  ui_story_5086_50860100_77_dialog_content = "Maya, come quick! Some suspicious-looking people are trying to get into the aquarium!",
  ui_story_5086_50860100_78_dialog_content = "<color=#e8d9bb>A couple of children appear in the doorway, frantically blocking two heavily-clothed people from entering.</color>",
  ui_story_5086_50860100_79_dialog_content = "Skado! Sebastian! Defensive formations! Don't let either of those two breach the lobby!",
  ui_story_5086_50860100_80_dialog_content = "Easier said than done, Froude! The shorty shouldn't be a problem, but how are we supposed to stop that tall guy from getting in?",
  ui_story_5086_50860100_81_dialog_content = "Rats... Is this really the end?",
  ui_story_5086_50860100_82_dialog_content = "Heheheh, you children are so energetic, but I can assure you, we're not bad guys.",
  ui_story_5086_50860100_83_dialog_content = "That's exactly what a bad guy would say!",
  ui_story_5086_50860100_84_dialog_content = "Besides, who wears this much clothing to the aquarium when it's this hot outside?",
  ui_story_5086_50860100_85_dialog_content = "If you can't appreciate the coolness of our outfits, then you still have a long way to go before you can call yourselves swashbucklers like us.",
  ui_story_5086_50860100_86_dialog_content = "Swash-what now?",
  ui_story_5086_50860100_87_dialog_content = "Wha—You mean you don't know about the world's coolest profession? Then allow me to—",
  ui_story_5086_50860100_88_dialog_content = "Alright you two, that's enough now.",
  ui_story_5086_50860100_89_dialog_content = "!",
  ui_story_5086_50860100_90_dialog_content = "<color=#e8d9bb>At some point during their bickering, Maya has somehow managed to appear behind them.</color>",
  ui_story_5086_50860100_91_dialog_content = "<color=#e8d9bb>With a single deft motion, she snatches their sunglasses and masks from their faces.</color>",
  ui_story_5086_50860100_92_dialog_content = "Goldie? Sadie?",
  ui_story_5086_50860100_93_dialog_content = "Uh-oh...",
  ui_story_5086_50860100_94_dialog_content = "She snuck up on us without drawing our attention at all! Who in the world are you?",
  ui_story_5086_50860100_95_dialog_content = "My name's Maya. I'm an employee here in the aquarium.",
  ui_story_5086_50860100_96_dialog_content = "I'm sorry, but I have to ask you to avoid wearing such scary-looking clothing here. There are lots of kids running around in the aquarium, you know.",
  ui_story_5086_50860100_97_dialog_content = "Besides, wouldn't you rather enjoy seeing all the pretty sea creatures without wearing all of this?",
  ui_story_5086_50860100_98_dialog_content = "Humph, I didn't come here to have fun.",
  ui_story_5086_50860100_99_dialog_content = "I heard about something terrible happening in Harbor City. As a noble swashbuckler, I came here to carry out justice!",
  ui_story_5086_50860100_100_dialog_content = "Something terrible? In Harbor City?",
  ui_story_5086_50860100_101_dialog_content = "Please don't offend our guests, Maya.",
  ui_story_5086_50860100_102_dialog_content = "But Miss Stellandine—",
  ui_story_5086_50860100_103_dialog_content = "My apologies, everyone. My name is Stellandine, and I'm the proprietress of this aquarium.",
  ui_story_5086_50860100_104_dialog_content = "My employee can act a bit rashly sometimes. I'm sorry if this has negatively impacted your visit to our establishment today.",
  ui_story_5086_50860100_105_dialog_content = "No, we're at fault here too.",
  ui_story_5086_50860100_106_dialog_content = "Then as proprietress of the aquarium, please allow me to treat you all to a meal as a token of our apology.",
  ui_story_5086_50860100_107_dialog_content = "Before then, feel free to observe any of the exhibits we have to offer.",
  ui_story_5086_50860100_108_dialog_content = "But just as Maya says, many of our guests are small children, so please refrain from any behavior that might upset them.",
  ui_story_5086_50860100_109_dialog_content = "If you have any further questions, you may ask me at any time.",
  ui_story_5086_50860100_110_dialog_content = "We won't interrupt your viewing any longer. Come along, Maya.",
  ui_story_5086_50860100_111_dialog_content = "But the display sign at the entrance...",
  ui_story_5086_50860100_112_dialog_content = "I still need to sort out a few files. Could you please help me with this?",
  ui_story_5086_50860100_113_dialog_content = "Sure thing! Just leave it to me!",
  ui_story_5086_50860100_114_dialog_content = "What a kindhearted boss.",
  ui_story_5086_50860100_115_dialog_content = "Anyway, there are so many familiar faces here today.",
  ui_story_5086_50860100_116_dialog_content = "The last time something like this happened was in the Andersen Haunted House, and then...",
  ui_story_5086_50860100_117_dialog_content = "Even though I don't think something like that will happen again, I should ask about it just to be safe.",
  ui_story_5086_50860100_118_dialog_content = "Hey Sadie, what's this terrible thing you heard about?",
  ui_story_5086_50860100_119_dialog_content = "Ah yes, that terrible thing! Any real swashbuckler would come running at even the faintest hint of trouble!",
  ui_story_5086_50860100_120_dialog_content = "So... Does that mean you came here just because you heard a rumor?",
  ui_story_5086_50860100_121_dialog_content = "It may have been just a rumor, but seeing is believing after all.",
  ui_story_5086_50860100_122_dialog_content = "If there's any sign of danger, I have a duty to confront it. Even if it turns out to be a rumor, I won't feel at ease until I see the truth for myself.",
  ui_story_5086_50860100_123_dialog_content = "Preventing even the most unlikely of crises from happening is all part of being a swashbuckler!",
  ui_story_5086_50860100_124_dialog_content = "The truth is, we did come across a number of troubling rumors.",
  ui_story_5086_50860100_125_dialog_content = "But each one was a little different from the last. Some people claimed that a colossal whale was lurking in the waters of Harbor City, waiting to devour anyone foolish enough to swim in the sea.",
  ui_story_5086_50860100_126_dialog_content = "Others claimed that people kept disappearing after picking up strange cards scattered around the town.",
  ui_story_5086_50860100_127_dialog_content = "It was too difficult to discern the truth all the way from Umbraton, so Sadie insisted on coming here and checking things out for herself.",
  ui_story_5086_50860100_128_dialog_content = "There's always a chance that this may lead to a glorious and fateful battle, one that will make my name famous throughout the land.",
  ui_story_5086_50860100_129_dialog_content = "I was a little worried about Sadie coming out here alone, so I decided to tag along.",
  ui_story_5086_50860100_130_dialog_content = "But really, we didn't expect to run into you here, PlayerName. What a happy coincidence!",
  ui_story_5086_50860100_131_dialog_content = "I see Mr. Minos is here as well, we better go say hello. Care to come along, PlayerName?",
  ui_story_5086_50860100_132_dialog_content = "Actually, I have something important to deal with right now.",
  ui_story_5086_50860100_133_dialog_content = "Okay then, hopefully we'll see you around again!",
  ui_story_5086_50860100_134_dialog_content = "Sure.",
  ui_story_5086_50860100_135_dialog_content = "(If only I could run into Jeno's message like this too.)",
  ui_story_5086_50860201_1_dialog_content = "This is exhausting.",
  ui_story_5086_50860201_2_dialog_content = "I've been going in circles all day, but I still haven't found anything.",
  ui_story_5086_50860201_3_dialog_content = "Maybe I'll just go take a break in the rest area for now.",
  ui_story_5086_50860201_4_dialog_content = "Jeno said that he left a message for me here, which means he most likely entrusted it to someone.",
  ui_story_5086_50860201_5_dialog_content = "Since he also included this aquarium's address, it must mean that this person is somewhere around here.",
  ui_story_5086_50860201_6_dialog_content = "Those are the only two clues I have right now.",
  ui_story_5086_50860201_7_dialog_content = "I'm pretty sure it's just a coincidence that so many of my friends are also here, but maybe one of them is the messenger? If so, am I supposed to ask them about it?",
  ui_story_5086_50860201_8_dialog_content = "No, that would defeat the purpose of keeping things a secret. It'd be no different than telling all of Astra about it.",
  ui_story_5086_50860201_9_dialog_content = "That concludes today's interactive event, everyone! It's time for our lovely starfish to go home for some well-deserved rest.",
  ui_story_5086_50860201_10_dialog_content = "It's also time for you kids to go home. Remember not to play in the street on the way back.",
  ui_story_5086_50860201_11_dialog_content = "Aww! But it's still so early! I don't wanna go home yet! And you still haven't told us a story yet!",
  ui_story_5086_50860201_12_dialog_content = "Your stories are always so much fun, Maya!",
  ui_story_5086_50860201_13_dialog_content = "I wanna hear one too.",
  ui_story_5086_50860201_14_dialog_content = "You promised us a story last week, but it looks like you already forgot about it, Maya.",
  ui_story_5086_50860201_15_dialog_content = "Oh, is that so? I really must've forgotten... Sorry.",
  ui_story_5086_50860201_16_dialog_content = "Come sit with us, Maya.",
  ui_story_5086_50860201_17_dialog_content = "Alright, I'll tell you a story I read the other day, but after that, you have to go straight home. Deal?",
  ui_story_5086_50860201_18_dialog_content = "Deal!",
  ui_story_5086_50860201_19_dialog_content = "A long, long time ago, there was a boy who got lost during his travels...",
  ui_story_5086_50860201_20_dialog_content = "(Well, Jeno probably didn't know when I would come looking for his message.)",
  ui_story_5086_50860201_21_dialog_content = "(Rather than entrusting it to a traveler, he most likely chose someone who is almost always at the aquarium.)",
  ui_story_5086_50860201_22_dialog_content = "(Aside from Maya, the only other person who fits the bill is the proprietress...)",
  ui_story_5086_50860201_23_dialog_content = "(Once she's done telling her story, I'll try to bring it up discreetly.)",
  ui_story_5086_50860201_24_dialog_content = "He traveled through dense forests and empty deserts and even reached the shores of the sea at the edge of the world. But all the while, he could never figure out which direction he was going.",
  ui_story_5086_50860201_25_dialog_content = "He sounds kinda silly to me.",
  ui_story_5086_50860201_26_dialog_content = "If I were him, I would bring tons of maps with me so I'd never get lost.",
  ui_story_5086_50860201_27_dialog_content = "I see! You like to prepare for everything, don't you Skado?",
  ui_story_5086_50860201_28_dialog_content = "But the boy in this story wasn't so fortunate.",
  ui_story_5086_50860201_29_dialog_content = "Even though he was usually surrounded by his friends, there were some journeys that he had to face alone.",
  ui_story_5086_50860201_30_dialog_content = "But thankfully, a little kitty cat appeared to save him from his loneliness.",
  ui_story_5086_50860201_31_dialog_content = "It was a very friendly cat. With nothing else to do, the boy decided to play with it.",
  ui_story_5086_50860201_32_dialog_content = "So the two took a stroll across the beach and watched the foamy waves breaking over the coral reef.",
  ui_story_5086_50860201_33_dialog_content = "They watched as flying fish leaped out of the water with a whistling noise.",
  ui_story_5086_50860201_34_dialog_content = "They rolled in the sand and laughed as they watched a bumbling crab stagger back and forth.",
  ui_story_5086_50860201_35_dialog_content = "At the end of the day, they curled up under a palm tree and let the soft sea breeze carry them off to sleep.",
  ui_story_5086_50860201_36_dialog_content = "That sounds so nice!",
  ui_story_5086_50860201_37_dialog_content = "When the little boy woke up, he was shocked to see a small town before his eyes.",
  ui_story_5086_50860201_38_dialog_content = "I say it was a small town, but it was as bustling as a big city. There were weapon shops, item shops, and all kinds of inns.",
  ui_story_5086_50860201_39_dialog_content = "The streets were full of brave adventurers equipped with all kinds of weapons and armor, as well as travelers in wonderful attire.",
  ui_story_5086_50860201_40_dialog_content = "In fact, there was a sea monster lurking somewhere in the town.",
  ui_story_5086_50860201_41_dialog_content = "During the day, everything was perfectly peaceful. But at night, a wailing sound could be heard coming from the sea.",
  ui_story_5086_50860201_42_dialog_content = "It was such a terrifying sound, so everyone thought it was the cry of a sea monster.",
  ui_story_5086_50860201_43_dialog_content = "That must be why there were so many adventurers in the town! I bet they thought that whoever defeated the monster could claim its treasure!",
  ui_story_5086_50860201_44_dialog_content = "That makes sense, since there are lots of people who think like you, Froude. But why were there so many travelers too?",
  ui_story_5086_50860201_45_dialog_content = "If there was a monster in that town, I'd never want to go there for anything.",
  ui_story_5086_50860201_46_dialog_content = "Maybe it was because the monster never showed its real face, even though its cries were so scary. No matter how many people showed up, it never appeared before anyone.",
  ui_story_5086_50860201_47_dialog_content = "Although there were plenty of people who claimed to have seen the monster, the rest of the town found out they were all lying.",
  ui_story_5086_50860201_48_dialog_content = "So the rumors surrounding the scary monster only got worse.",
  ui_story_5086_50860201_49_dialog_content = "(Hey, I've read that story before too.)",
  ui_story_5086_50860201_50_dialog_content = "(If I remember correctly, it ends with the boy and the cat discovering a hidden cave.)",
  ui_story_5086_50860201_51_dialog_content = "(Instead of finding a sea monster in there, all they found was a little girl crying by herself.)",
  ui_story_5086_50860201_52_dialog_content = "(She had no family or friends, so she spent every single night crying alone in that cave.)",
  ui_story_5086_50860201_53_dialog_content = "(Her quiet sobbing echoed through the cave until the whole town could hear it, which was how the sea monster rumors got started.)",
  ui_story_5086_50860201_54_dialog_content = "(The little boy cheered her up and promised to be her friend.)",
  ui_story_5086_50860201_55_dialog_content = "(After that, the village never heard the \"sea monster\" at night, but...)",
  ui_story_5086_50860201_56_dialog_content = "But...",
  ui_story_5086_50860201_57_dialog_content = "(Huh? She's already at this part of the story?)",
  ui_story_5086_50860201_58_dialog_content = "Unfortunately, I don't remember the rest of the story!",
  ui_story_5086_50860201_59_dialog_content = "Pffft! Cough, cough...",
  ui_story_5086_50860201_60_dialog_content = "I knew it...",
  ui_story_5086_50860201_61_dialog_content = "This isn't surprising at all...",
  ui_story_5086_50860201_62_dialog_content = "It's fine, we're used to it already.",
  ui_story_5086_50860201_63_dialog_content = "We all know how bad Maya's memory is, after all. Sometimes she even forgets things that happened five minutes ago.",
  ui_story_5086_50860201_64_dialog_content = "It really makes us worry.",
  ui_story_5086_50860201_65_dialog_content = "Hahaha, I'm not really sure how to proceed...",
  ui_story_5086_50860201_66_dialog_content = "What would you kids do if you were in the little boy's shoes?",
  ui_story_5086_50860201_67_dialog_content = "Oh, I know! I would go straight to a weapon shop to buy a new sword and shield!",
  ui_story_5086_50860201_68_dialog_content = "I don't like fighting, but I would buy some healing potion just to be safe.",
  ui_story_5086_50860201_69_dialog_content = "You both make good points. I'm sure the little boy thinks that way too.",
  ui_story_5086_50860201_70_dialog_content = "(Not at all! And when did this turn into a high fantasy story?)",
  ui_story_5086_50860201_71_dialog_content = "After buying a full set of gear, the little boy departed for the sea monster's lair and challenged it to a final battle.",
  ui_story_5086_50860201_72_dialog_content = "He underwent years of training and overcame countless obstacles—",
  ui_story_5086_50860201_73_dialog_content = "(The story only takes place in a small town, though!)",
  ui_story_5086_50860201_74_dialog_content = "The massive sea monster finally acknowledged the boy's power and bravery, and so it rose from the depths to accept his challenge!",
  ui_story_5086_50860201_75_dialog_content = "\"You wish to claim my treasure? Then you must first defeat me in battle!\"",
  ui_story_5086_50860201_76_dialog_content = "The sea monster laughed arrogantly at the little boy.",
  ui_story_5086_50860201_77_dialog_content = "(I've definitely read these lines somewhere else before! She's starting to tell a completely different story!)",
  ui_story_5086_50860201_78_dialog_content = "Wow!",
  ui_story_5086_50860201_79_dialog_content = "And so the boy drew his blade and engaged the enormous beast in one final battle!",
  ui_story_5086_50860302_1_dialog_content = "<color=#e8d9bb>As the children cheer excitedly at Maya's story, a few more people enter the rest area.</color>",
  ui_story_5086_50860302_2_dialog_content = "Looks like we can take a quick break over here, Sadie.",
  ui_story_5086_50860302_3_dialog_content = "But we still haven't found any clues regarding the terrible thing happening here!",
  ui_story_5086_50860302_4_dialog_content = "It may seem calm and peaceful around here, but someone might be in desperate need of our help right now. We can't afford to slack off.",
  ui_story_5086_50860302_5_dialog_content = "I know how you feel, but you've been running around ever since you woke up this morning.",
  ui_story_5086_50860302_6_dialog_content = "We've almost searched half of the city for signs of danger. At this rate, we'll burn out before we manage to help anyone.",
  ui_story_5086_50860302_7_dialog_content = "Balancing work and rest, staying in top physical condition—",
  ui_story_5086_50860302_8_dialog_content = "That's how idols stay on top of their games... and I'm sure the same applies to swashbucklers.",
  ui_story_5086_50860302_9_dialog_content = "Goldie...",
  ui_story_5086_50860302_10_dialog_content = "What is it?",
  ui_story_5086_50860302_11_dialog_content = "What you said just now... It was actually pretty cool.",
  ui_story_5086_50860302_12_dialog_content = "I understand. I'll go rest as hard as I can right now!",
  ui_story_5086_50860302_13_dialog_content = "Uh, sure. Let's just spend the next few hours regaining our strength.",
  ui_story_5086_50860302_14_dialog_content = "We've already scouted out Harbor City during the day, so maybe our next move is to watch over the city at night.",
  ui_story_5086_50860302_15_dialog_content = "After all, lots of things only show themselves under the cover of darkness.",
  ui_story_5086_50860302_16_dialog_content = "I couldn't have said it better myself, Miss Goldie.",
  ui_story_5086_50860302_17_dialog_content = "Sanae, you would do well to conduct a night-time observation as well.",
  ui_story_5086_50860302_18_dialog_content = "Ah... Understood! As soon as we get back... No, I'll get started on planning my new investigation task right now!",
  ui_story_5086_50860302_19_dialog_content = "I meant to ask you about it before.",
  ui_story_5086_50860302_20_dialog_content = "What exactly are you two investigating? What new industry is Nina trying to break into?",
  ui_story_5086_50860302_21_dialog_content = "I ask that you refrain from looking to me for answers, Sanae. This is your task, after all.",
  ui_story_5086_50860302_22_dialog_content = "Uh... O-Okay then, allow me to explain...",
  ui_story_5086_50860302_23_dialog_content = "Well, um, you see, Miss Nina says that a real business person doesn't stick to just one industry, and so...",
  ui_story_5086_50860302_24_dialog_content = "And so, she wants to create a chain of businesses by expanding beyond the haunted house.",
  ui_story_5086_50860302_25_dialog_content = "Plenty of changes have been happening here in Harbor City, so Miss Nina asked us to come and look for potential business opportunities.",
  ui_story_5086_50860302_26_dialog_content = "Like purchasing a well-known aquarium and using it to train new employees, then opening a similar one in Umbraton... or something like that...",
  ui_story_5086_50860302_27_dialog_content = "The idea of opening an aquarium in Umbraton fills my head with some pretty scary images...",
  ui_story_5086_50860302_28_dialog_content = "Don't you think you guys should reconsider? Umbraton has ever had anything like that before, as far as I know.",
  ui_story_5086_50860302_29_dialog_content = "That's... That's what makes it such a unique opportunity! Umbraton is also close to a body of water, so it makes sense.",
  ui_story_5086_50860302_30_dialog_content = "It's not you guys that I'm worried about, but your future visitors.",
  ui_story_5086_50860302_31_dialog_content = "But Miss Nina is adamant about establishing this chain of businesses... which is why I have to...",
  ui_story_5086_50860302_32_dialog_content = "A-Anyway, I still have to ask if they want to sell the aquarium—",
  ui_story_5086_50860302_33_dialog_content = "We'd never do that!",
  ui_story_5086_50860302_34_dialog_content = "Maya? Weren't you telling those kids a story? ... Oh, they already went home.",
  ui_story_5086_50860302_35_dialog_content = "I don't know what you two are after, but—",
  ui_story_5086_50860302_36_dialog_content = "This aquarium exists to bring a smile to every guest who comes through its doors.",
  ui_story_5086_50860302_37_dialog_content = "It's a place full of fond and happy memories, and it matters a lot to the people here.",
  ui_story_5086_50860302_38_dialog_content = "No amount of money could ever buy it.",
  ui_story_5086_50860302_39_dialog_content = "Ah... I-I'm sorry...",
  ui_story_5086_50860302_40_dialog_content = "Are you being rude to our guests again, Maya?",
  ui_story_5086_50860302_41_dialog_content = "I don't think I said anything wrong.",
  ui_story_5086_50860302_42_dialog_content = "You think so too, don't you Miss Stellandine? After all, you're the one who has given up the most for the sake of this aquarium.",
  ui_story_5086_50860302_43_dialog_content = "Heheh, I'm glad you think so highly of me, Maya.",
  ui_story_5086_50860302_44_dialog_content = "But we still have to make some money.",
  ui_story_5086_50860302_45_dialog_content = "How else can I take care of you and the rest of our friends here in the aquarium?",
  ui_story_5086_50860302_46_dialog_content = "They've already been forced out of their homes in the sea. All I can do is make their lives here as comfortable as possible.",
  ui_story_5086_50860302_47_dialog_content = "I've been doing my best to make money and take care of everyone too! Um... Just a second, please!",
  ui_story_5086_50860302_48_dialog_content = "Take a look at this, Miss Stellandine! I've already made two hundred and thirty-three Nightium for us!",
  ui_story_5086_50860302_49_dialog_content = "That's incredible, Maya! I'm sure the piggy bank in your room has been fed well too.",
  ui_story_5086_50860302_50_dialog_content = "Heehee!",
  ui_story_5086_50860302_51_dialog_content = "If you ever run into any money troubles, you can always count on me to help, Miss Stellandine!",
  ui_story_5086_50860302_52_dialog_content = "I don't mind giving you every last Nightium if it's for the aquarium.",
  ui_story_5086_50860302_53_dialog_content = "Thank you, Maya. I'll be counting on you.",
  ui_story_5086_50860302_54_dialog_content = "Just leave it to me!",
  ui_story_5086_50860302_55_dialog_content = "My... How very surprising.",
  ui_story_5086_50860302_56_dialog_content = "Did you say anything? Minos?",
  ui_story_5086_50860302_57_dialog_content = "Nothing at all, my dear friend. Pay me no heed, I'm simply taking a few inconsequential notes.",
  ui_story_5086_50860302_58_dialog_content = "After all, observing the local cultural environment is also a part of our investigation.",
  ui_story_5086_50860302_59_dialog_content = "You're as diligent as ever, Minos.",
  ui_story_5086_50860302_60_dialog_content = "But of course.",
  ui_story_5086_50860401_1_dialog_content = "Since everyone has already gathered here, perhaps it's time to make good on my word.",
  ui_story_5086_50860401_2_dialog_content = "Would you care to join us for lunch?",
  ui_story_5086_50860401_3_dialog_content = "Sure! I was just starting to feel hungry too.",
  ui_story_5086_50860401_4_dialog_content = "I have no idea what Harbor City's food is like, but I'm really looking forward to trying it.",
  ui_story_5086_50860401_5_dialog_content = "Maya, let's show our guests to the restaurant.",
  ui_story_5086_50860401_6_dialog_content = "Okay! Right this way, everyone!",
  ui_story_5086_50860401_7_dialog_content = "Are we going too, Minos?",
  ui_story_5086_50860401_8_dialog_content = "Please do not concern yourselves for our sake.",
  ui_story_5086_50860401_9_dialog_content = "Sanae still needs to compile her report for this morning's findings.",
  ui_story_5086_50860401_10_dialog_content = "Once she finishes her work, I will escort her to the restaurant.",
  ui_story_5086_50860401_11_dialog_content = "Please enjoy your meal.",
  ui_story_5086_50860401_12_dialog_content = "Huh? I-I mean... yes, we'll be along shortly.",
  ui_story_5086_50860401_13_dialog_content = "Keep up the good work, Sanae.",
  ui_story_5086_50860401_14_dialog_content = "I... I'll do my best...",
  ui_story_5086_50860401_15_dialog_content = "We'll see you guys in a bit then... Wait, which way did Maya and Stellandine go?",
  ui_story_5086_50860401_16_dialog_content = "Beyond the shark exhibit on the left is a staircase. Follow it up to the second floor and turn left, then you will find the restaurant.",
  ui_story_5086_50860401_17_dialog_content = "Thanks, Minos.",
  ui_story_5086_50860401_18_dialog_content = "Turn left on the second floor... Huh, I wonder why Minos knows how to get here...",
  ui_story_5086_50860401_19_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5086_50860401_20_dialog_content = "Ouch...",
  ui_story_5086_50860401_21_dialog_content = "Maya! I'm sorry, I didn't see you running this way.",
  ui_story_5086_50860401_22_dialog_content = "Are you okay?",
  ui_story_5086_50860401_23_dialog_content = "Heehee, I'm fine! Besides, I should be the one apologizing.",
  ui_story_5086_50860401_24_dialog_content = "I was so busy leading the way that I forgot to see if you were still following... Ah!",
  ui_story_5086_50860401_25_dialog_content = "<color=#e8d9bb>With a start, Maya suddenly pulls out her notebook and flips through it frantically.</color>",
  ui_story_5086_50860401_26_dialog_content = "Oh no. Where did I write it down?",
  ui_story_5086_50860401_27_dialog_content = "What are you looking for?",
  ui_story_5086_50860401_28_dialog_content = "I'm so sorry, sir.",
  ui_story_5086_50860401_29_dialog_content = "But it looks like I forgot to write down your name!",
  ui_story_5086_50860401_30_dialog_content = "I don't think you'll find it in your notes. After all, I still haven't properly introduced myself.",
  ui_story_5086_50860401_31_dialog_content = "My name is PlayerName, and I'm a Caelestite. It's a pleasure to meet you, Maya.",
  ui_story_5086_50860401_32_dialog_content = "I'm Maya, a trainee working in the aquarium!",
  ui_story_5086_50860401_X32_dialog_content = "And now that we've introduced ourselves, that makes us friends!",
  ui_story_5086_50860401_33_dialog_content = "This way, PlayerName! It wasn't easy, but I saved the best seat in the house just for you.",
  ui_story_5086_50860401_34_dialog_content = "Wow, I can see the entire tank from up here!",
  ui_story_5086_50860401_35_dialog_content = "What an incredible view to go along with our lunch!",
  ui_story_5086_50860401_36_dialog_content = "The restaurant is so big and luxurious too. Is this really a part of the aquarium?",
  ui_story_5086_50860401_37_dialog_content = "You're very perceptive, PlayerName.",
  ui_story_5086_50860401_38_dialog_content = "Strictly speaking, this restaurant does not belong solely to our aquarium, no.",
  ui_story_5086_50860401_39_dialog_content = "Due to the rapid development of tourist resorts in the area, some of the smaller local businesses have suffered serious financial setbacks.",
  ui_story_5086_50860401_40_dialog_content = "To alleviate some of the strain, a number of business owners have decided to band together to compete in the burgeoning tourism industry.",
  ui_story_5086_50860401_41_dialog_content = "This restaurant is just one of those endeavors.",
  ui_story_5086_50860401_42_dialog_content = "Everyone works really hard for this restaurant, and the food here is amazing!",
  ui_story_5086_50860401_43_dialog_content = "On my first day here, I was determined to eat every single dish on the menu.",
  ui_story_5086_50860401_44_dialog_content = "But up until today, I've only been able to try a few of them.",
  ui_story_5086_50860401_45_dialog_content = "There's still plenty of time, Maya. No need to rush.",
  ui_story_5086_50860401_46_dialog_content = "Now then, what should we eat today?",
  ui_story_5086_50860401_47_dialog_content = "That depends, what did we eat yesterday? Hmm...",
  ui_story_5086_50860401_48_dialog_content = "I didn't write it down in my notes. Did I forget to do that too?",
  ui_story_5086_50860401_49_dialog_content = "Oh well, order whatever you like—",
  ui_story_5086_50860401_50_dialog_content = "I'll go ask one of the servers about what you ate yesterday.",
  ui_story_5086_50860401_51_dialog_content = "Oh, you don't have to do that. It's not a big deal or anything.",
  ui_story_5086_50860401_52_dialog_content = "But you set a goal for yourself, didn't you Maya?",
  ui_story_5086_50860401_53_dialog_content = "It's no trouble at all. Even if you forget your orders, the restaurant has a menu just for you actually.",
  ui_story_5086_50860401_54_dialog_content = "You're always so willing to help everyone, so they want to help you realize your goal too.",
  ui_story_5086_50860401_55_dialog_content = "I'll be right back.",
  ui_story_5086_50860401_56_dialog_content = "Miss Stellandine is such a nice person.",
  ui_story_5086_50860401_57_dialog_content = "Right? She is the nicest person in the whole world!",
  ui_story_5086_50860401_58_dialog_content = "She's so kind and gentle, and she personally takes care of every single animal in the aquarium.",
  ui_story_5086_50860401_59_dialog_content = "Not only that, but she told me the aquarium could be my home when I didn't have a place to go.",
  ui_story_5086_50860401_60_dialog_content = "Huh? So does that mean you're new here?",
  ui_story_5086_50860401_61_dialog_content = "Seriously, PlayerName? I know I'm forgetful and kind of a klutz, but I'm not completely hopeless, you know!",
  ui_story_5086_50860401_62_dialog_content = "If I had been here for a long time, do you really think I would still be a trainee?",
  ui_story_5086_50860401_63_dialog_content = "I could say a lot more about this... but you do make a pretty good point, Maya.",
  ui_story_5086_50860401_64_dialog_content = "You seem to be really popular around here.",
  ui_story_5086_50860401_65_dialog_content = "Even though your poor memory kept you from remembering the ending of your story, the children loved it all the same.",
  ui_story_5086_50860401_66_dialog_content = "Huh? What story?",
  ui_story_5086_50860401_67_dialog_content = "The one you told the kids in the rest area earlier.",
  ui_story_5086_50860401_68_dialog_content = "Oh, did I really tell them a story?",
  ui_story_5086_50860401_69_dialog_content = "<size=50>You mean you already forgot?</size>",
  ui_story_5086_50860401_70_dialog_content = "Well, it doesn't look like I wrote it down in my notes—",
  ui_story_5086_50860401_71_dialog_content = "If you had to write down every little detail like that, I don't think a single notebook would be enough for one day.",
  ui_story_5086_50860401_72_dialog_content = "But you still remember the story, so you can tell it to me! Please, PlayerName, I really want to hear it!",
  ui_story_5086_50860401_73_dialog_content = "T-Too close! I'll tell you the story, but just give me some space—",
  ui_story_5086_50860401_74_dialog_content = "Let's see, it was about a little boy...",
  ui_story_5086_50860402_1_dialog_content = "What an exciting story. Did you come up with it again, Maya?",
  ui_story_5086_50860402_2_dialog_content = "Miss Stellandine! You can read minds?",
  ui_story_5086_50860402_3_dialog_content = "No, Maya, it's just that your stories are so very special.",
  ui_story_5086_50860402_4_dialog_content = "No matter what happens in them, or if the characters are good or bad—",
  ui_story_5086_50860402_5_dialog_content = "Your stories always end with everyone coming together and living happily ever after.",
  ui_story_5086_50860402_6_dialog_content = "Well, that's just how fairy tales are supposed to go, even the ones I make up.",
  ui_story_5086_50860402_7_dialog_content = "...",
  ui_story_5086_50860402_8_dialog_content = "I suppose you're right. Besides, even if you read a sad story, you'll forget it by the very next day.",
  ui_story_5086_50860402_9_dialog_content = "Still, Maya's forgetfulness is a lot more serious than anything I've ever seen. Shouldn't we be more concerned about it?",
  ui_story_5086_50860402_10_dialog_content = "Perhaps... But I took her to see a doctor, and her health results were perfectly normal.",
  ui_story_5086_50860402_11_dialog_content = "The doctor couldn't identify the source of her forgetfulness either.",
  ui_story_5086_50860402_12_dialog_content = "It can't be easy, living like this...",
  ui_story_5086_50860402_13_dialog_content = "No kidding. How else are you supposed to keep up with a manga if you can't even remember what happened in the last issue?",
  ui_story_5086_50860402_14_dialog_content = "And what about all the cool things you've seen in life? No experiences in the world amount to much if you can't even remember them.",
  ui_story_5086_50860402_15_dialog_content = "Sadie! You shouldn't talk about Miss Maya like that, or anyone else for that matter. It's rude.",
  ui_story_5086_50860402_16_dialog_content = "Ah, you're right. Sorry about that, Maya.",
  ui_story_5086_50860402_17_dialog_content = "Aww... Poor Miss Maya.",
  ui_story_5086_50860402_18_dialog_content = "Hey, we're not supposed to talk about people like that.",
  ui_story_5086_50860402_19_dialog_content = "I know, but... when I think about how hard her life must be, I...",
  ui_story_5086_50860402_20_dialog_content = "Miss Maya, why don't you become a maid like me?",
  ui_story_5086_50860402_21_dialog_content = "The work can be a little tough sometimes... but you'll always be surrounded by good people...",
  ui_story_5086_50860402_22_dialog_content = "?",
  ui_story_5086_50860402_23_dialog_content = "Thanks, everyone! Though I don't really know what's going on, you all seem really concerned for me.",
  ui_story_5086_50860402_24_dialog_content = "But you should know, I'm actually really happy here.",
  ui_story_5086_50860402_25_dialog_content = "See? If something important happens in my life, I always write it down in my notes so I don't forget.",
  ui_story_5086_50860402_26_dialog_content = "I got lost yesterday while walking around. A sweet old lady in an apron helped me find my way and even gave me an orange.",
  ui_story_5086_50860402_27_dialog_content = "That's because you saved her grandson from drowning in the ocean that day. She was thanking you, Maya.",
  ui_story_5086_50860402_28_dialog_content = "The day before that, I forgot that our fridge was broken, so I couldn't make any ice for some of our animals. But thankfully, a kind snack vendor gave me a big bucket of it.",
  ui_story_5086_50860402_29_dialog_content = "I remember that as well. You were helping him attract more customers, since his business was doing so poorly that day. You came up with some really over-the-top ideas too.",
  ui_story_5086_50860402_30_dialog_content = "Last week, when I lost my flow chart for our interactive event, the children teamed up to help me run the show. It was incredible!",
  ui_story_5086_50860402_31_dialog_content = "No one was willing to participate at first, but thanks to Maya's ability to work so well with children, the event became a smashing success.",
  ui_story_5086_50860402_32_dialog_content = "And the week before that, and last month, and even last year...",
  ui_story_5086_50860402_33_dialog_content = "<color=#e8d9bb>Every page of Maya's notebook is full of bright and positive memories.</color>",
  ui_story_5086_50860402_34_dialog_content = "<color=#e8d9bb>She describes these colorful moments of her everyday life with perfect clarity.</color>",
  ui_story_5086_50860402_35_dialog_content = "<color=#e8d9bb>Suddenly, a card falls out from the notebook's pages.</color>",
  ui_story_5086_50860402_36_dialog_content = "<color=#e8d9bb>Scribbled on it are a few lines of writing. Though the handwriting is child-like in appearance, it carries a certain gravity.</color>",
  ui_story_5086_50860402_37_dialog_content = "What did you record on that card, Maya?",
  ui_story_5086_50860402_38_dialog_content = "Oh, this? It's me!",
  ui_story_5086_50860402_39_dialog_content = "You?",
  ui_story_5086_50860402_40_dialog_content = "That's right! Whenever something super-duper-extra important happens in my life, I write it on this card and read it every single day.",
  ui_story_5086_50860402_41_dialog_content = "Even though I can't remember anything written on it, these memories are a huge part of me.",
  ui_story_5086_50860402_42_dialog_content = "<color=#e8d9bb>Maya gently picks up the card and closes her eyes.</color>",
  ui_story_5086_50860402_43_dialog_content = "<color=#e8d9bb>Clearly, she has no need to look at the card to know what it says.</color>",
  ui_story_5086_50860402_44_dialog_content = "\"Elvis wishes me a long and happy life.\"",
  ui_story_5086_50860402_45_dialog_content = "\"Miss Stellandine gave me a home in her aquarium.\"",
  ui_story_5086_50860402_46_dialog_content = "\"I love everyone here in Harbor City.\"",
  ui_story_5086_50860402_47_dialog_content = "Oh, Miss Maya...",
  ui_story_5086_50860402_48_dialog_content = "If you ever want to visit Umbraton, I'll make sure to take good care of you. It's the least a swashbuckler could do.",
  ui_story_5086_50860402_49_dialog_content = "I think you have the potential to become an idol too, Miss Maya. Want to give it a shot?",
  ui_story_5086_50860402_50_dialog_content = "Huh? Wait, I just said that I really enjoy my life here. I don't want to go anywhere else—",
  ui_story_5086_50860402_51_dialog_content = "Miss Stellandine, she brought up someone named Elvis just now...",
  ui_story_5086_50860402_52_dialog_content = "The city lord, yes. He was kind enough to take care of Maya in the past, since she had no parents to speak of and her memory was still unreliable. This much was known to everyone in town.",
  ui_story_5086_50860402_53_dialog_content = "She was also known for running about town and lending a hand to anyone in need.",
  ui_story_5086_50860402_54_dialog_content = "For that reason, some of our town's residents took to calling her the Pauper Princess of Harbor City.",
  ui_story_5086_50860402_55_dialog_content = "When Harbor City fell under attack during the recent crisis, Maya appeared to have vanished as well.",
  ui_story_5086_50860402_56_dialog_content = "No one knew if something had happened to her, or if the city lord had something to do with it...",
  ui_story_5086_50860402_57_dialog_content = "Since she can't remember anything about it, discerning the truth is all but impossible now.",
  ui_story_5086_50860402_58_dialog_content = "All I know is that a few days after the incident, she suddenly showed up at the entrance of the aquarium, asking for a job.",
  ui_story_5086_50860402_59_dialog_content = "Seeing that she no longer had a guardian, I offered to let her live and work here as a trainee.",
  ui_story_5086_50860402_60_dialog_content = "I never did anything particularly special, yet she writes about me as though I'm some sort of saint.",
  ui_story_5086_50860402_61_dialog_content = "Honestly...",
  ui_story_5086_50860402_62_dialog_content = "(Elvis used to look after her... Could it be that Jeno chose Maya to be his messenger?)",
  ui_story_5086_50860402_63_dialog_content = "Miss Stellandine, I might have a way to help Maya recover some of her memories.",
  ui_story_5086_50860402_64_dialog_content = "Really?",
  ui_story_5086_50860402_65_dialog_content = "Yes, and I think there's a good chance that it'll work too.",
  ui_story_5086_50860402_66_dialog_content = "I see.",
  ui_story_5086_50860402_67_dialog_content = "As much as I would like to accept your offer, as Maya's temporary guardian, I think she should be the one to decide.",
  ui_story_5086_50860500_1_dialog_content = "You say you can help me recover my memories?",
  ui_story_5086_50860500_2_dialog_content = "I had no idea you could do something so amazing, PlayerName!",
  ui_story_5086_50860500_3_dialog_content = "As a Caelestite, I can use my psychic abilities to connect with people's minds. I still haven't fully mastered my powers, but I can definitely use them for something like this.",
  ui_story_5086_50860500_4_dialog_content = "By delving into your memories, I might be able to find something that you have no way of seeing for yourself.",
  ui_story_5086_50860500_5_dialog_content = "The power to connect with people's minds... Is that what it is?",
  ui_story_5086_50860500_6_dialog_content = "Yeah, more or less.",
  ui_story_5086_50860500_7_dialog_content = "Hmm... Let me just look at my notes one more time.",
  ui_story_5086_50860500_8_dialog_content = "?",
  ui_story_5086_50860500_9_dialog_content = "...",
  ui_story_5086_50860500_10_dialog_content = "Sorry, but I can't do that.",
  ui_story_5086_50860500_11_dialog_content = "Huh? Is it because there's something you don't want me to see?",
  ui_story_5086_50860500_12_dialog_content = "No, that's not it.",
  ui_story_5086_50860500_13_dialog_content = "It's just that I'm not supposed to disturb my ancestor's dream.",
  ui_story_5086_50860500_14_dialog_content = "Your ancestor?",
  ui_story_5086_50860500_15_dialog_content = "That's right. My forgotten memories are probably with my ancestor right now, along with my parents.",
  ui_story_5086_50860500_16_dialog_content = "That's why I'm not really rushing things to get them back right now.",
  ui_story_5086_50860500_17_dialog_content = "It feels a little lonely sometimes, but I can bear it.",
  ui_story_5086_50860500_18_dialog_content = "Because one day, when my dream finally ends, I'll be able to regain everything I've lost.",
  ui_story_5086_50860500_19_dialog_content = "Uh, Maya... What are you talking about?",
  ui_story_5086_50860500_20_dialog_content = "You mean you don't know, PlayerName?",
  ui_story_5086_50860500_21_dialog_content = "This whole world is just a dream.",
  ui_story_5086_50860500_22_dialog_content = "What do you mean? We're clearly in the real world right now. Pinch your cheeks, if you don't believe me!",
  ui_story_5086_50860500_23_dialog_content = "And even if we were in a dream, whose dream would it be? Yours?",
  ui_story_5086_50860500_24_dialog_content = "A dream is just a dream. Yours is no different than mine, or anyone else's.",
  ui_story_5086_50860500_25_dialog_content = "My parents saw me in their dreams, which is the only reason I'm here in the first place.",
  ui_story_5086_50860500_26_dialog_content = "My ancestor is also watching over me from within the dream.",
  ui_story_5086_50860500_27_dialog_content = "So you think we're all just characters inside of some dream, Maya?",
  ui_story_5086_50860500_28_dialog_content = "Of course not! Everyone's just living in a bubble, that's all. As for those important people we've lost... they're living in the sweetest dream of all, taking care of us.",
  ui_story_5086_50860500_29_dialog_content = "So who exactly is your ancestor?",
  ui_story_5086_50860500_30_dialog_content = "The progenitor of my entire bloodline, an undersea guardian whose gaze sees beyond the flow of time.",
  ui_story_5086_50860500_31_dialog_content = "Or at least that's what my ancestor just said.",
  ui_story_5086_50860500_32_dialog_content = "That's why I shouldn't disturb the other world for something as little as getting my memories back.",
  ui_story_5086_50860500_33_dialog_content = "I definitely shouldn't disturb my ancestor about it either.",
  ui_story_5086_50860500_34_dialog_content = "I still feel pretty lost right now...",
  ui_story_5086_50860500_35_dialog_content = "I'm sorry...",
  ui_story_5086_50860500_36_dialog_content = "But what I do understand is that there's something more important to you than retrieving your memories.",
  ui_story_5086_50860500_37_dialog_content = "!",
  ui_story_5086_50860500_38_dialog_content = "Even though I'm really curious to know more about it... I won't force you to do anything you're not willing to do, Maya.",
  ui_story_5086_50860500_39_dialog_content = "PlayerName...",
  ui_story_5086_50860500_40_dialog_content = "I really like you!",
  ui_story_5086_50860500_41_dialog_content = "Huh? No, wait... Uh... I'm still...",
  ui_story_5086_50860500_42_dialog_content = "We've been over this before, Maya. You can't say things like that to boys so casually.",
  ui_story_5086_50860500_43_dialog_content = "I also really like you, Miss Stellandine!",
  ui_story_5086_50860500_44_dialog_content = "Oh, you sweet child... Never mind. There's still work to do this afternoon, so try to get some rest for now.",
  ui_story_5086_50860500_45_dialog_content = "But I want to listen to a fairy tale.",
  ui_story_5086_50860500_46_dialog_content = "Since I've already forgotten the story from this morning, listening to a new one is my way of resting!",
  ui_story_5086_50860500_47_dialog_content = "You really seem to enjoy fairy tales, Maya.",
  ui_story_5086_50860500_48_dialog_content = "That's because they're records of different dreams.",
  ui_story_5086_50860500_49_dialog_content = "And I love seeing all kinds of different dreams.",
  ui_story_5086_50860500_50_dialog_content = "Records of dreams, huh...",
  ui_story_5086_50860500_51_dialog_content = "Alright, then. I do happen to have a story worth telling right now.",
  ui_story_5086_50860500_52_dialog_content = "It's about a little girl and a hopeless dream.",
  ui_story_5086_50860500_53_dialog_content = "Yay! You're the best, Miss Stellandine!",
  ui_story_5086_50860500_54_dialog_content = "Once upon a time, there was a girl who lived under the sea.",
  ui_story_5086_50860500_55_dialog_content = "The sea provided all kinds of things for her—delicious food, bountiful treasure, and all the toys and amusement she could ever want.",
  ui_story_5086_50860500_56_dialog_content = "But there were also many things missing from her world, like fire and noise... and love.",
  ui_story_5086_50860500_57_dialog_content = "One day, during a dangerous storm, the young girl rescued a young prince who had fallen from his ship. Naturally, she fell head over heels in love with him.",
  ui_story_5086_50860500_58_dialog_content = "Wow! A prince from the land and a princess from the sea!",
  ui_story_5086_50860500_59_dialog_content = "Soon after, the prince's crew pulled him back onto the ship, and they returned to their kingdom. A long time passed, but the prince never came back.",
  ui_story_5086_50860500_60_dialog_content = "What? But why...",
  ui_story_5086_50860500_61_dialog_content = "So the girl paid a visit to the witch of the sea and offered her most prized possession in exchange for the power to walk on land.",
  ui_story_5086_50860500_62_dialog_content = "When she finally made it to the shore, she struggled to use her new legs. But she was determined to see the prince again, so she crawled until she could walk, and walked until she could run...",
  ui_story_5086_50860500_63_dialog_content = "Yeah! Don't give up, princess! You can do it!",
  ui_story_5086_50860500_64_dialog_content = "But that was when the girl discovered something terrible had happened. In exchange for her new legs, the witch had taken away what she cherished the most—her memories of her beloved prince.",
  ui_story_5086_50860500_65_dialog_content = "She stood in a crowd of unfamiliar people, her lover's face and voice a complete mystery to her now.",
  ui_story_5086_50860500_66_dialog_content = "In fact, the girl began to doubt whether she had truly been in love to begin with.",
  ui_story_5086_50860500_67_dialog_content = "She had no way of meeting the one she loved ever again.",
  ui_story_5086_50860500_68_dialog_content = "What happened next?",
  ui_story_5086_50860500_69_dialog_content = "Nothing, my dear. This is how the story ends.",
  ui_story_5086_50860500_70_dialog_content = "Huh? B-But the girl hasn't found her prince yet!",
  ui_story_5086_50860500_71_dialog_content = "She didn't get her memories back either! She can't even remember what he looks like anymore!",
  ui_story_5086_50860500_72_dialog_content = "It's such a sad and hopeless story...",
  ui_story_5086_50860500_73_dialog_content = "You told it so well, Miss Stellandine... but I can't help but feel sad now...",
  ui_story_5086_50860500_74_dialog_content = "Maya...",
  ui_story_5086_50860500_75_dialog_content = "I feel the same way! Why... Why does life have to be so unfair to that poor girl?",
  ui_story_5086_50860500_76_dialog_content = "Sanae? And everyone else... How long have you guys been here?",
  ui_story_5086_50860500_77_dialog_content = "Ever since the story started, of course! See? Sadie's pulling her hat down because she doesn't want anyone to see her tears.",
  ui_story_5086_50860500_78_dialog_content = "I'm not crying. This is just how swashbucklers show their respect and gratitude.",
  ui_story_5086_50860500_79_dialog_content = "Uh-huh, whatever you say!",
  ui_story_5086_50860500_80_dialog_content = "Still, I'm surprised so many people haven't heard this fairy tale before. I always thought it was a pretty well-known story.",
  ui_story_5086_50860500_81_dialog_content = "I'm only interested in swashbuckler stories.",
  ui_story_5086_50860500_82_dialog_content = "If there were any swashbucklers in her world, I'm sure they would help her get her memories back in an instant.",
  ui_story_5086_50860500_83_dialog_content = "You're right, but even without a hero like that, I'm sure someone would be willing to help her.",
  ui_story_5086_50860500_84_dialog_content = "Fairy tales aren't supposed to have sad endings.",
  ui_story_5086_50860500_85_dialog_content = "But... It's possible that the prince already forgot about her... In fact, he might have already married another princess...",
  ui_story_5086_50860500_86_dialog_content = "Meanwhile, the poor girl was left all alone on the shore... It's so tragic... *sobbing*",
  ui_story_5086_50860500_87_dialog_content = "Um, Sanae? It's just a story, you know.",
  ui_story_5086_50860500_88_dialog_content = "Waaaaaaah—",
  ui_story_5086_50860500_89_dialog_content = "Oh no, Sanae won't stop crying... Do something, Manae! Please!",
  ui_story_5086_50860500_90_dialog_content = "...",
  ui_story_5086_50860500_91_dialog_content = "Waaaaaah! Why did the girl have to pay such a terrible price? That witch is nothing but a big meanie! And why didn't the prince ever come looking for her? Waaaaaaah!",
  ui_story_5086_50860500_92_dialog_content = "Why are you making it worse, Manae?",
  ui_story_5086_50860500_93_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860500_94_dialog_content = "<color=#e8d9bb>Suddenly, a soft song begins to play.</color>",
  ui_story_5086_50860500_95_dialog_content = "<color=#e8d9bb>As light and distant as the gentle sea breeze, the melody rises and falls like waves rising from the quiet ocean floor.</color>",
  ui_story_5086_50860500_96_dialog_content = "<color=#e8d9bb>Every note rings out clearly from the conch in Maya's hands.</color>",
  ui_story_5086_50860500_97_dialog_content = "<color=#e8d9bb>For a moment, every person's mind drifts away to the tune of her song...</color>",
  ui_story_5086_50860500_98_dialog_content = "<color=#e8d9bb>With their hearts eased by the melody, they begin to forget all about their troubles.</color>",
  ui_story_5086_50860500_99_dialog_content = "What a beautiful song... What was that just now, Miss Maya?",
  ui_story_5086_50860500_100_dialog_content = "I don't know much about music, but that song made me think about my favorite swashbuckler manga just now.",
  ui_story_5086_50860500_101_dialog_content = "I am deeply honored to have had the privilege of hearing such a splendid song.",
  ui_story_5086_50860500_102_dialog_content = "You're here too, Minos? ... Huh?",
  ui_story_5086_50860500_103_dialog_content = "When did Sanae fall asleep?",
  ui_story_5086_50860500_104_dialog_content = "Maya's music has the power to calm people's hearts. It's especially useful in situations like this.",
  ui_story_5086_50860500_105_dialog_content = "I'm certain this child is having a wonderful dream as we speak.",
  ui_story_5086_50860500_106_dialog_content = "Yep. Now that she's forgotten all about her sadness, she can finally relax.",
  ui_story_5086_50860500_107_dialog_content = "Young Sanae has been striving to complete the task given to her by our lady. This is a perfect opportunity for her to get some rest.",
  ui_story_5086_50860500_108_dialog_content = "Behind the aquarium are the living quarters for our employees. There are plenty of rooms available.",
  ui_story_5086_50860500_109_dialog_content = "If you don't mind, she's more than welcome to sleep there.",
  ui_story_5086_50860500_110_dialog_content = "The rest of you are free to make use of those rooms as well.",
  ui_story_5086_50860500_111_dialog_content = "I believe I will do just that. Your hospitality is very much appreciated, Miss Stellandine.",
  ui_story_5086_50860500_112_dialog_content = "Mr. PlayerName, could you please help me escort Sanae to her room?",
  ui_story_5086_50860500_113_dialog_content = "Me? Yeah, sure.",
  ui_story_5086_50860500_114_dialog_content = "You have my thanks.",
  ui_story_5086_50860601_1_dialog_content = "Minos, was there any specific reason you asked me to help you?",
  ui_story_5086_50860601_2_dialog_content = "I beg your pardon?",
  ui_story_5086_50860601_3_dialog_content = "I could understand if anyone else asked for my help, but this is you we're talking about.",
  ui_story_5086_50860601_4_dialog_content = "For Minos, the all-powerful butler of the Andersen family, to ask for my help is just as unlikely as the Cloud Gardens being the exact center of the entire universe.",
  ui_story_5086_50860601_5_dialog_content = "I believe you regard me with far too much esteem, my friend. However, it is exactly as you suspect.",
  ui_story_5086_50860601_6_dialog_content = "You are aware of the conflict that recently befell Harbor City, yes?",
  ui_story_5086_50860601_7_dialog_content = "... I am.",
  ui_story_5086_50860601_8_dialog_content = "It seems you are far more knowledgeable about the situation than you care to admit.",
  ui_story_5086_50860601_9_dialog_content = "I-Is it that obvious?",
  ui_story_5086_50860601_10_dialog_content = "I am merely making another small observation, nothing more.",
  ui_story_5086_50860601_11_dialog_content = "But I digress. In the last ten years, City Lord Elvis sacrificed both blood and sweat in equally large measures for the sake of Harbor City.",
  ui_story_5086_50860601_12_dialog_content = "It was thanks to his efforts that this town became a place of such peace and prosperity.",
  ui_story_5086_50860601_13_dialog_content = "But in the wake of that recent incident and his disappearance, Harbor City fell under the administration of Lumopolis.",
  ui_story_5086_50860601_14_dialog_content = "It is for this exact reason that Miss Nina believes Harbor City is ripe with business opportunities.",
  ui_story_5086_50860601_15_dialog_content = "But it is also worth noting that when an organization is caught in the midst of turmoil, maggots are wont to breed in even the smallest corners.",
  ui_story_5086_50860601_16_dialog_content = "What are you trying to say?",
  ui_story_5086_50860601_17_dialog_content = "I'm sure you've noticed it by now, Mr. PlayerName. All sorts of strange and disturbing rumors have been circulating in and around Harbor City.",
  ui_story_5086_50860601_18_dialog_content = "I fear that the city's recent strife is to blame for them, and these foul rumors only serve to devalue Harbor City in the eyes of the world.",
  ui_story_5086_50860601_19_dialog_content = "Now that you mention it, Sadie and Goldie only came here from Umbraton because they heard something disturbing about Harbor City.",
  ui_story_5086_50860601_20_dialog_content = "But even now, they still haven't found anything to substantiate the rumors.",
  ui_story_5086_50860601_21_dialog_content = "It's all so strange. I'm not surprised that Sadie came for this sort of thing, but why did Goldie tag along too?",
  ui_story_5086_50860601_22_dialog_content = "Does she sense danger here too?",
  ui_story_5086_50860601_23_dialog_content = "... Wait.",
  ui_story_5086_50860601_24_dialog_content = "My suspicions were correct last time, weren't they? This is similar to what happened back when I first met you, Minos...",
  ui_story_5086_50860601_25_dialog_content = "Are you telling me something terrible like that is about to happen again?",
  ui_story_5086_50860601_26_dialog_content = "Of course not. I am but a humble butler, not a prophet.",
  ui_story_5086_50860601_27_dialog_content = "Phew, that's a relief.",
  ui_story_5086_50860601_28_dialog_content = "However, I did make a number of unsettling discoveries while conducting our business investigation.",
  ui_story_5086_50860601_29_dialog_content = "For example, there have been several instances of travelers disappearing in Harbor City.",
  ui_story_5086_50860601_30_dialog_content = "Furthermore, each of them expressed a certain desire shortly before going missing—",
  ui_story_5086_50860601_31_dialog_content = "Namely, that they wanted to go to the aquarium.",
  ui_story_5086_50860601_32_dialog_content = "This aquarium really lives up to its reputation!",
  ui_story_5086_50860601_33_dialog_content = "All of the fish are so lively in here. It's like they just pulled them out of the sea today.",
  ui_story_5086_50860601_34_dialog_content = "Haha... Ha...",
  ui_story_5086_50860601_35_dialog_content = "Hey... Where is everyone?",
  ui_story_5086_50860601_36_dialog_content = "Hello? Is anybody there? I could use some help here!",
  ui_story_5086_50860601_37_dialog_content = "It's a little too dark in here. Aren't they supposed to have a lighted exit sign for people to see?",
  ui_story_5086_50860601_38_dialog_content = "Oh, I see light over there! I'm pretty sure that leads to the lobby, so I'll just—",
  ui_story_5086_50860601_39_dialog_content = "... What's that smell?",
  ui_story_5086_50860601_40_dialog_content = "Is... someone there?",
  ui_story_5086_50860601_41_dialog_content = "Huh? Wh-What are you...",
  ui_story_5086_50860601_42_dialog_content = "Ahhhhhhh!",
  ui_story_5086_50860602_1_dialog_content = "Gah!",
  ui_story_5086_50860602_2_dialog_content = "D-Don't scare me like that, Minos!",
  ui_story_5086_50860602_3_dialog_content = "My apologies. I only meant to share the information I had acquired with you.",
  ui_story_5086_50860602_4_dialog_content = "\"The unadulterated truth is often the most terrifying.\" Have you heard this saying before?",
  ui_story_5086_50860602_5_dialog_content = "Compared to a superficial peace of mind, I feel much more comforted when I know the entire truth behind every detail.",
  ui_story_5086_50860602_6_dialog_content = "You must have nerves of steel, Minos.",
  ui_story_5086_50860602_7_dialog_content = "So long as my lady requires it, an entire city can be built upon my unmoving nerves.",
  ui_story_5086_50860602_8_dialog_content = "... I can't tell if you're joking or not anymore.",
  ui_story_5086_50860602_9_dialog_content = "That hardly matters now.",
  ui_story_5086_50860602_10_dialog_content = "What truly matters is, have you gotten any rest during this brief respite?",
  ui_story_5086_50860602_11_dialog_content = "... I have.",
  ui_story_5086_50860602_12_dialog_content = "Wonderful. It would be unforgivable of me to upset a dear friend of Miss Nina with my words.",
  ui_story_5086_50860602_13_dialog_content = "If you excuse me, I must attend to young Sanae now.",
  ui_story_5086_50860602_14_dialog_content = "Huh?",
  ui_story_5086_50860602_15_dialog_content = "I wonder why Minos felt the need to share all of this with me...",
  ui_story_5086_50860602_16_dialog_content = "It didn't feel like he was trying to scare me or anything.",
  ui_story_5086_50860602_17_dialog_content = "Still, it's possible that all of the disappearances are somehow connected to the aquarium...",
  ui_story_5086_50860602_18_dialog_content = "Based on my experiences, whenever something strange like this happens, the first culprit I have to suspect is—",
  ui_story_5086_50860602_19_option_content = "Psychic Scan!",
  ui_story_5086_50860602_20_dialog_content = "!",
  ui_story_5086_50860602_21_dialog_content = "No way... I didn't expect this, but I sensed the presence of an Eclipsite in the aquarium!",
  ui_story_5086_50860602_22_dialog_content = "It's too faint to pinpoint its exact location... Where could it be?",
  ui_story_5086_50860602_23_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860602_24_dialog_content = "It disappeared? Wait... I've heard this song before...",
  ui_story_5086_50860602_25_dialog_content = "...",
  ui_story_5086_50860602_26_dialog_content = "Maya?",
  ui_story_5086_50860602_27_dialog_content = "Shhh.",
  ui_story_5086_50860602_28_dialog_content = "He's sleeping.",
  ui_story_5086_50860602_29_dialog_content = "<color=#e8d9bb>Maya steps away to reveal a little boy sleeping on the bench.</color>",
  ui_story_5086_50860602_30_dialog_content = "It's that kid from before... Froude, right? Why hasn't he gone home yet?",
  ui_story_5086_50860602_31_dialog_content = "The whales here are his favorite animals, so he likes to sneak out after he goes home to come visit them.",
  ui_story_5086_50860602_32_dialog_content = "I usually find him hanging out in the whale exhibit around this time. Whenever I do, I just tell him another fairy tale, and he goes right back home.",
  ui_story_5086_50860602_33_dialog_content = "Heheh, I know all of this because I wrote it down in my notes.",
  ui_story_5086_50860602_34_dialog_content = "So what story did you tell him, Maya?",
  ui_story_5086_50860602_35_dialog_content = "Well, since I could only remember half of it, I had to fill in the rest by playing my conch.",
  ui_story_5086_50860602_36_dialog_content = "Now that you're here, PlayerName... You can tell us a story!",
  ui_story_5086_50860602_37_dialog_content = "But Froude is already asleep.",
  ui_story_5086_50860602_38_dialog_content = "Didn't you know, PlayerName? They say you can still remember things even when you hear them in your sleep.",
  ui_story_5086_50860602_39_dialog_content = "You just want to hear another story, don't you?",
  ui_story_5086_50860602_40_dialog_content = "Haha, guilty as charged!",
  ui_story_5086_50860602_41_dialog_content = "... I think I'm starting to understand how Miss Stellandine feels.",
  ui_story_5086_50860602_42_dialog_content = "(It's almost impossible to say no to Maya.)",
  ui_story_5086_50860602_43_dialog_content = "Do you still remember the story Miss Stellandine told us earlier?",
  ui_story_5086_50860602_44_dialog_content = "What? Miss Stellandine told us a story?",
  ui_story_5086_50860602_45_dialog_content = "I should've known... That's okay, I'll just tell it to you again.",
  ui_story_5086_50860602_46_dialog_content = "Once upon a time, there was a girl who lived in the sea. She rescued a young prince when he fell out of his ship...",
  ui_story_5086_50860602_47_dialog_content = "Uh-huh!",
  ui_story_5086_50860602_48_dialog_content = "... And so the girl made a deal with a sea witch, who gave her the ability to walk on land.",
  ui_story_5086_50860602_49_dialog_content = "But when the girl made it to the shore, she realized that the price she paid for her new legs were her memories of the prince she loved so much.",
  ui_story_5086_50860602_50_dialog_content = "How could this be? Without her memories, won't she feel lonely?",
  ui_story_5086_50860602_51_dialog_content = "...",
  ui_story_5086_50860602_52_dialog_content = "Don't worry! The story isn't over yet!",
  ui_story_5086_50860602_53_dialog_content = "Now how did the rest of it go again?",
  ui_story_5086_50860602_54_dialog_content = "Oh, right! Even after the prince returned to his kingdom, he couldn't stop thinking about the beautiful girl who had saved his life.",
  ui_story_5086_50860602_55_dialog_content = "So he returned to the sea where the two of them first met, but the girl was nowhere to be found.",
  ui_story_5086_50860602_56_dialog_content = "Even so, the prince refused to give up. He called upon the creatures of the sea and asked each of them if they knew where she went.",
  ui_story_5086_50860602_57_dialog_content = "First, he asked a whale...",
  ui_story_5086_50860602_58_dialog_content = "<color=#e8d9bb>Splash.</color>",
  ui_story_5086_50860602_59_dialog_content = "<color=#e8d9bb>Maya's conch begins making sounds again.</color>",
  ui_story_5086_50860602_60_dialog_content = "<color=#e8d9bb>As if drawn to it, a whale appears on the other side of the glass and gracefully swims to and fro.</color>",
  ui_story_5086_50860602_61_dialog_content = "Then, he asked a flounder...",
  ui_story_5086_50860602_62_dialog_content = "<color=#e8d9bb>In another tank, a school of flounder zip past them.</color>",
  ui_story_5086_50860602_63_dialog_content = "After that, he asked a crab...",
  ui_story_5086_50860602_64_dialog_content = "<color=#e8d9bb>From a nearby beach exhibit, several crabs poke their heads out of the sand.</color>",
  ui_story_5086_50860602_65_dialog_content = "<color=#e8d9bb>Countless water sprites gather quietly around Maya and dance to the melody of her conch.</color>",
  ui_story_5086_50860602_66_dialog_content = "With their help, the prince journeys to the farthest edge of the sea.",
  ui_story_5086_50860602_67_dialog_content = "And there, on the beach, he is finally reunited with the girl who saved him.",
  ui_story_5086_50860602_68_dialog_content = "\"Who are you?\" she asks with a look of bewilderment.",
  ui_story_5086_50860602_69_dialog_content = "\"I am yours at long last,\" he replies. \"I love you.\"",
  ui_story_5086_50860602_70_dialog_content = "And the two lived happily ever after.",
  ui_story_5086_50860602_71_dialog_content = "The moment their hands touched, the girl's memories came flooding back into her heart.",
  ui_story_5086_50860602_72_dialog_content = "When it comes to fairy tales, love is always stronger than even the most powerful magic. It's the answer to every problem!",
  ui_story_5086_50860701_1_dialog_content = "What a great story! Could you tell me another? Please?!",
  ui_story_5086_50860701_2_dialog_content = "Alright, let's see...",
  ui_story_5086_50860701_3_dialog_content = "Attention, visitors and staff. Due to an unforeseen emergency, the aquarium will be closing at an earlier time today.",
  ui_story_5086_50860701_4_dialog_content = "Please follow our staff members to the lobby as soon as possible.",
  ui_story_5086_50860701_5_dialog_content = "That was Miss Stellandine's voice. I wonder what happened...",
  ui_story_5086_50860701_6_dialog_content = "A visitor has reported the disappearance of a friend. The aquarium is cooperating with the city guard to investigate the matter.",
  ui_story_5086_50860701_7_dialog_content = "Let's go take a look.",
  ui_story_5086_50860701_8_dialog_content = "Wait—",
  ui_story_5086_50860701_9_dialog_content = "Those Eclipsites better watch out! I won't tolerate any treachery on my watch!",
  ui_story_5086_50860701_10_dialog_content = "Sadie, relax! They might just get separated; we don't know anything for sure yet.",
  ui_story_5086_50860701_11_dialog_content = "If Super Swashbuckler Sadie can't keep calm in this situation, normal people will panic even more.",
  ui_story_5086_50860701_12_dialog_content = "Miss Stellandine! Is everyone okay?!",
  ui_story_5086_50860701_13_dialog_content = "Huff... Even though he's just a little kid, carrying him all the way here was torture on my arms and legs...",
  ui_story_5086_50860701_14_dialog_content = "Good, Maya and PlayerName are here as well... Hmm? Where did this child come from?",
  ui_story_5086_50860701_15_dialog_content = "Maya says he sneaked in to see the whales.",
  ui_story_5086_50860701_16_dialog_content = "Just set him down in that chair for now.",
  ui_story_5086_50860701_17_dialog_content = "I believe everyone in the aquarium is now present and accounted for.",
  ui_story_5086_50860701_18_dialog_content = "Are you able to confirm that, Miss Stellandine?",
  ui_story_5086_50860701_19_dialog_content = "I remember the faces of every visitor. But if you still have doubts...",
  ui_story_5086_50860701_20_dialog_content = "Is anyone else missing a friend or companion?",
  ui_story_5086_50860701_21_dialog_content = "<color=#e8d9bb>Everyone present glanced around, shaking their heads.</color>",
  ui_story_5086_50860701_22_dialog_content = "Nobody...",
  ui_story_5086_50860701_23_dialog_content = "(Minos must know something. I should go ask him.)",
  ui_story_5086_50860701_24_dialog_content = "Hey, Minos... Huh? Where did he go? He was just here a second ago.",
  ui_story_5086_50860701_25_dialog_content = "I saw him escorting someone down that hallway.",
  ui_story_5086_50860701_26_dialog_content = "Thanks, Goldie.",
  ui_story_5086_50860701_27_dialog_content = "Heheh, you can leave this place to me, now go do your thing!",
  ui_story_5086_50860701_28_dialog_content = "There's no way he would've left me behind without saying anything!",
  ui_story_5086_50860701_29_dialog_content = "The aquarium isn't that big. An adult couldn't have gotten lost in here for this long!",
  ui_story_5086_50860701_30_dialog_content = "No... Something must've happened to him!",
  ui_story_5086_50860701_31_dialog_content = "*sobbing* It's all my fault... I never should've insisted on coming here!",
  ui_story_5086_50860701_32_dialog_content = "Please remain calm. We don't know anything for sure yet.",
  ui_story_5086_50860701_33_dialog_content = "We should focus on searching for clues and finding your friend.",
  ui_story_5086_50860701_34_dialog_content = "Fortunately, a very helpful Caelestite has just appeared before us.",
  ui_story_5086_50860701_35_dialog_content = "I'm sorry?",
  ui_story_5086_50860701_36_dialog_content = "<color=#e8d9bb>Minos asks the distraught visitor to return to the group and signals me to join him further down the hall.</color>",
  ui_story_5086_50860701_37_dialog_content = "It's so dark in here.",
  ui_story_5086_50860701_38_dialog_content = "According to Miss Stellandine, the lighting system has been malfunctioning as of late.",
  ui_story_5086_50860701_39_dialog_content = "She claims to have shut down the aquarium for maintenance in the past, so today's electrical problems were completely unexpected.",
  ui_story_5086_50860701_40_dialog_content = "Thankfully, only the main lighting fixtures in this hall have lost power.",
  ui_story_5086_50860701_41_dialog_content = "The ambient lights are faint, but they should suffice for navigating through the hallway.",
  ui_story_5086_50860701_42_dialog_content = "Anyway, I believe the last known location of the missing visitor was in this very place.",
  ui_story_5086_50860701_43_dialog_content = "What makes you say that?",
  ui_story_5086_50860701_44_dialog_content = "Please take a look at this pillar.",
  ui_story_5086_50860701_45_dialog_content = "What's that? There's something smeared on it... Wait, is this blood?!",
  ui_story_5086_50860701_46_dialog_content = "Is there more in the area?",
  ui_story_5086_50860701_47_dialog_content = "<color=#e8d9bb>Splash.</color>",
  ui_story_5086_50860701_48_dialog_content = "Whoa, that was close... I almost slipped on this puddle. Watch your step, Minos.",
  ui_story_5086_50860701_49_dialog_content = "I could say the very same to you, PlayerName. Until this incident is resolved, please exercise the utmost caution at the scene—",
  ui_story_5086_50860701_50_dialog_content = "We must avoid damaging any clues or evidence.",
  ui_story_5086_50860701_51_dialog_content = "If you had taken one more step, you would have ruined that footprint on the floor.",
  ui_story_5086_50860701_52_dialog_content = "Oh, now you tell me!",
  ui_story_5086_50860701_53_dialog_content = "Wait, there's more than one footprint here... I'm glad you were able to spot them even in this lighting.",
  ui_story_5086_50860701_54_dialog_content = "But they're all mixed together...",
  ui_story_5086_50860701_55_dialog_content = "Based on the height provided by the missing person's friend, I can estimate their approximate shoe size.",
  ui_story_5086_50860701_56_dialog_content = "And judging from the way they overlap with one another, I can roughly discern the order in which they were made, as well.",
  ui_story_5086_50860701_57_dialog_content = "Lastly, given the way that the footprints lead past this blood-smeared pillar, it is highly possible that they belong to our missing person.",
  ui_story_5086_50860701_58_dialog_content = "That was fast!",
  ui_story_5086_50860701_59_dialog_content = "Still, there's something weird about these footprints.",
  ui_story_5086_50860701_60_dialog_content = "They look totally normal on their way to the middle of the hallway, but then they double back and turn into a complete mess.",
  ui_story_5086_50860701_61_dialog_content = "Almost as if... the person who left them ran into something scary.",
  ui_story_5086_50860701_62_dialog_content = "I believe you have the makings of a skilled detective, my friend.",
  ui_story_5086_50860701_63_dialog_content = "I, too, made a similar observation.",
  ui_story_5086_50860701_64_dialog_content = "A normal person would naturally cry out for help when confronted with something terrifying.",
  ui_story_5086_50860701_65_dialog_content = "From the look of these footprints, I would assume he had enough time to shout.",
  ui_story_5086_50860701_66_dialog_content = "Unfortunately, my inquiries with the rest of the aquarium's visitors revealed that none of them were even close to this hallway earlier this afternoon.",
  ui_story_5086_50860701_67_dialog_content = "Those who had been through here reported nothing out of the ordinary as well, meaning that the missing person's time of disappearance cannot be determined based on our present knowledge.",
  ui_story_5086_50860701_68_dialog_content = "Actually, Maya and I were close by when it happened...",
  ui_story_5086_50860701_69_dialog_content = "But Maya was playing her conch the whole time, which may explain why we didn't hear anything.",
  ui_story_5086_50860701_70_dialog_content = "I see. How unfortunate.",
  ui_story_5086_50860701_71_dialog_content = "It appears the current trail of clues can only lead us this far.",
  ui_story_5086_50860701_72_dialog_content = "The footprints stop just before they reach the end of the hallway... So where could this person have gone?",
  ui_story_5086_50860701_73_dialog_content = "... Wait, I just remembered something!",
  ui_story_5086_50860701_74_dialog_content = "After we finished our conversation earlier, I sensed the presence of an Eclipsite somewhere inside the aquarium! It was faint, but there was no mistaking it!",
  ui_story_5086_50860701_75_dialog_content = "Is it possible that there are hidden rooms and passages in this place, just like the haunted house?",
  ui_story_5086_50860701_76_dialog_content = "So they could lurk in the dark, and come out when the lights go out.",
  ui_story_5086_50860701_77_dialog_content = "The missing visitor ran into an Eclipsite and was attacked while attempting to escape...",
  ui_story_5086_50860702_1_dialog_content = "Until we searched every corner of this aquarium, I could not deny the possibility of hidden rooms existing within this place.",
  ui_story_5086_50860702_2_dialog_content = "However, we must face yet another pressing issue...",
  ui_story_5086_50860702_3_dialog_content = "Are we done yet? How much longer must we waste our time here?",
  ui_story_5086_50860702_4_dialog_content = "Just let the city guard deal with this. Handling cases of missing persons is their job, isn't it?",
  ui_story_5086_50860702_5_dialog_content = "I understand your concerns, everyone. The city guard has already been notified, but it would be best if everyone remains here until they arrive.",
  ui_story_5086_50860702_6_dialog_content = "Honestly, there's something seriously wrong with this place, and I'm not sticking around to find out what it is! I'll make sure to tell my friends to steer clear of this place, too!",
  ui_story_5086_50860702_7_dialog_content = "Please don't say that! We're...",
  ui_story_5086_50860702_8_dialog_content = "Given the current circumstances, we simply don't have the time to conduct such a thorough inspection.",
  ui_story_5086_50860702_9_dialog_content = "The guests are starting to get restless...",
  ui_story_5086_50860702_10_dialog_content = "Please forgive me.",
  ui_story_5086_50860702_11_dialog_content = "Wha—Hey!",
  ui_story_5086_50860702_12_dialog_content = "What gives, Minos? Why'd you shove me like that...",
  ui_story_5086_50860702_13_dialog_content = "Is something wrong, PlayerName?",
  ui_story_5086_50860702_14_dialog_content = "(Oh no, everyone's turning their attention towards me because I jumped in so suddenly!)",
  ui_story_5086_50860702_15_dialog_content = "Ahaha... S-Sorry to interrupt...",
  ui_story_5086_50860702_16_dialog_content = "But I think I know a way to uncover the truth!",
  ui_story_5086_50860702_17_dialog_content = "?!",
  ui_story_5086_50860702_18_dialog_content = "(W-Was that my voice?!)",
  ui_story_5086_50860702_19_dialog_content = "That's amazing, PlayerName!",
  ui_story_5086_50860702_20_dialog_content = "While everyone else was panicking, you were already hard at work trying to solve the mystery, huh?",
  ui_story_5086_50860702_21_dialog_content = "Your ability to take control of the situation is so impressive!",
  ui_story_5086_50860702_22_dialog_content = "Wow, PlayerName! I had no idea you wanted to be a detective instead of a swashbuckler like me!",
  ui_story_5086_50860702_23_dialog_content = "N-Now just hold on a minute! That wasn't me—",
  ui_story_5086_50860702_24_dialog_content = "That wasn't me just blowing hot air!",
  ui_story_5086_50860702_25_dialog_content = "Hey! Don't interrupt me—",
  ui_story_5086_50860702_26_dialog_content = "Because I'm about to point out the real culprit!",
  ui_story_5086_50860702_27_dialog_content = "... What?!?",
  ui_story_5086_50860702_28_dialog_content = "Huh? Are you really so surprised by this other side of you, PlayerName?",
  ui_story_5086_50860702_29_dialog_content = "Who do you think you are, pretending to be a detective right now? Read the room, you punk!",
  ui_story_5086_50860702_30_dialog_content = "Ah, leave him alone. He's just some kid.",
  ui_story_5086_50860702_31_dialog_content = "(They all think I'm a nutjob now!)",
  ui_story_5086_50860702_32_dialog_content = "But I really—",
  ui_story_5086_50860702_33_dialog_content = "Ahem.",
  ui_story_5086_50860702_34_dialog_content = "(Minos?!)",
  ui_story_5086_50860702_35_option_content = "Psychic Scan!",
  ui_story_5086_50860702_36_dialog_content = "(What's going on here, Minos?)",
  ui_story_5086_50860702_37_dialog_content = "(I will properly apologize to you at a later time, my friend. But as a butler, I'm not well-suited to standing in the spotlight.)",
  ui_story_5086_50860702_38_dialog_content = "(For this reason, I must ask you to cooperate with me, much in the way that Manae does with Sanae.)",
  ui_story_5086_50860702_39_dialog_content = "(So you need me to act as your puppet?)",
  ui_story_5086_50860702_40_dialog_content = "(If you would, yes.)",
  ui_story_5086_50860702_41_dialog_content = "Please listen, everybody! I discovered a few things in that hallway over there...",
  ui_story_5086_50860702_42_dialog_content = "... So when you put all of it together, especially the bloodstains on the pillar, it's likely that the missing person was attacked.",
  ui_story_5086_50860702_43_dialog_content = "Starting this afternoon, no one has left the aquarium yet. That also means—",
  ui_story_5086_50860702_44_dialog_content = "That the culprit hasn't left. In other words... The murderer is somewhere among us.",
  ui_story_5086_50860702_45_dialog_content = "Get real, kid! Are you seriously accusing us of something?!",
  ui_story_5086_50860702_46_dialog_content = "Your attention-seeking has gotten way out of hand! Besides, do you honestly think you can build a case with such flimsy evidence?!",
  ui_story_5086_50860702_47_dialog_content = "I knew it! I knew there was something wrong with this aquarium!",
  ui_story_5086_50860702_48_dialog_content = "Back when the Eclipsites attacked Harbor City, they must've turned some of the employees here into their own kind!",
  ui_story_5086_50860702_49_dialog_content = "What?! I'm not an Eclipsite at all! And don't you dare point any fingers at Miss Stellandine or the rest of our staff!",
  ui_story_5086_50860702_50_dialog_content = "That's right! You can't just accuse Maya or Stellandine like that, especially when you know nothing about them!",
  ui_story_5086_50860702_51_dialog_content = "PlayerName, while I'm grateful for your assistance in this investigation, I must ask that you refrain from baselessly accusing our guests of wrongdoing...",
  ui_story_5086_50860702_52_dialog_content = "(She's right, Minos! I told you I sensed an Eclipsite earlier, so doesn't that mean the culprit isn't one of them?)",
  ui_story_5086_50860702_53_dialog_content = "(Everyone's starting to suspect one another because of what you said!)",
  ui_story_5086_50860702_54_dialog_content = "(This is also part of the reason why I asked for your cooperation.)",
  ui_story_5086_50860702_55_dialog_content = "(You are an intelligent young man, but your lack of skepticism can be concerning at times.)",
  ui_story_5086_50860702_56_dialog_content = "(Huh?)",
  ui_story_5086_50860702_57_dialog_content = "Of course I can make these accusations! I'm a Caelestite, after all!",
  ui_story_5086_50860702_58_dialog_content = "I'm also a close friend of Lady Carleen. The knights of Lumopolis will be more than happy to verify all of this when they get here.",
  ui_story_5086_50860702_59_dialog_content = "As a Caelestite and a trusted ally of Lady Carleen, it's only natural that I would want to apprehend this criminal, don't you think?",
  ui_story_5086_50860702_60_dialog_content = "All I need to do is hold hands with everyone present, and my psychic abilities will allow me to find the true culprit.",
  ui_story_5086_50860702_61_dialog_content = "And what if you don't find the culprit among us?",
  ui_story_5086_50860702_62_dialog_content = "Then that would be the best possible outcome, wouldn't you agree?",
  ui_story_5086_50860702_63_dialog_content = "Huh...?",
  ui_story_5086_50860702_64_dialog_content = "Of course it would be great if we could root out the culprit here and now.",
  ui_story_5086_50860702_65_dialog_content = "But if I don't find him among you, that just means none of you are murderers, right?",
  ui_story_5086_50860702_66_dialog_content = "So either I'll find the criminal or prove everyone's innocence. It's a win-win situation, don't you think?",
  ui_story_5086_50860702_67_dialog_content = "That actually makes a lot of sense! Here, let me go first!",
  ui_story_5086_50860702_68_dialog_content = "I suppose you're right... Alright, I'll cooperate.",
  ui_story_5086_50860702_69_dialog_content = "(Wow... All these uncooperative people are suddenly lining up to help out.)",
  ui_story_5086_50860702_70_dialog_content = "(I know I'm supposed to be the puppet here, but Minos is leading the entire room by their noses.)",
  ui_story_5086_50860702_71_dialog_content = "(Also, it seems like none of them have considered the possibility that I don't actually know anything, or that I have no way of proving anyone's innocence...)",
  ui_story_5086_50860702_72_dialog_content = "(A natural response. After all, people become short-sighted quite easily during stressful situations such as this. When that happens, they only see things in black and white.)",
  ui_story_5086_50860702_73_dialog_content = "(But for the time being, please do not alert them to that possibility.)",
  ui_story_5086_50860702_74_dialog_content = "(Given our current circumstances, I believe uniting everybody under a common goal is of vital importance.)",
  ui_story_5086_50860702_75_dialog_content = "(I know... But...)",
  ui_story_5086_50860702_76_dialog_content = "(They all want me to shake their hands now! Do I really have to use my powers on every single one of them?)",
  ui_story_5086_50860702_77_dialog_content = "(Not at all, my friend.)",
  ui_story_5086_50860702_78_dialog_content = "(After all, I simply wish to observe...)",
  ui_story_5086_50860702_79_dialog_content = "(Which of these people will behave abnormally at such a critical juncture.)",
  ui_story_5086_50860702_80_dialog_content = "<color=#e8d9bb>Suddenly, the line of people waiting to shake hands stops abruptly.</color>",
  ui_story_5086_50860702_81_dialog_content = "What's the matter, Maya? It's your turn, you know.",
  ui_story_5086_50860702_82_dialog_content = "I...",
  ui_story_5086_50860702_83_dialog_content = "(That's right; Maya thinks that my powers will somehow disturb the Ancestor.)",
  ui_story_5086_50860702_84_dialog_content = "Don't worry, Maya, I...",
  ui_story_5086_50860702_85_dialog_content = "<color=#e8d9bb>Click!</color>",
  ui_story_5086_50860702_86_dialog_content = "What's going on?! Who turned out the lights?!",
  ui_story_5086_50860702_87_dialog_content = "Stay in line and remain calm, everyone—",
  ui_story_5086_50860702_88_dialog_content = "Someone locked the entrance! We're all trapped in here now!",
  ui_story_5086_50860702_89_dialog_content = "Out of my way! No door can stand up to—",
  ui_story_5086_50860702_90_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5086_50860702_91_dialog_content = "<color=#e8d9bb>Amidst the confusion, the sound of shattering glass pierces the air.</color>",
  ui_story_5086_50860702_92_dialog_content = "<color=#e8d9bb>Before anyone can react, the tank surrounding the aquarium's lobby explodes.</color>",
  ui_story_5086_50860702_93_dialog_content = "<color=#e8d9bb>The lobby is quickly inundated with cold water and countless fish.</color>",
  ui_story_5086_50860801_1_dialog_content = "PlayerName—!",
  ui_story_5086_50860801_2_dialog_content = "Urgh... Cough, cough, cough—",
  ui_story_5086_50860801_3_dialog_content = "Are you alright?",
  ui_story_5086_50860801_4_dialog_content = "Yeah, I just swallowed some water, that's all... Thanks for the save.",
  ui_story_5086_50860801_5_dialog_content = "Don't thank me, thank Goldie.",
  ui_story_5086_50860801_6_dialog_content = "Everyone got swept away when the tanks burst, but she managed to fish the two of us out of the water.",
  ui_story_5086_50860801_7_dialog_content = "It was just dumb luck, that's all.",
  ui_story_5086_50860801_8_dialog_content = "I was the furthest away from the tanks when they exploded, so I had a little more time to react.",
  ui_story_5086_50860801_9_dialog_content = "But I couldn't see anything in the dark just now, so I held onto the two people closest to me.",
  ui_story_5086_50860801_10_dialog_content = "Luckily, as the current was sweeping us away, I also managed to break open the door to this rest area and pull us out of the water.",
  ui_story_5086_50860801_11_dialog_content = "(That doesn't sound like dumb luck at all, Goldie...)",
  ui_story_5086_50860801_12_dialog_content = "Anyway... How did all of this happen...?",
  ui_story_5086_50860801_13_dialog_content = "<color=#e8d9bb>Water continues pouring through the cracks in the door, gradually raising the water level in the room.</color>",
  ui_story_5086_50860801_14_dialog_content = "I know it's an aquarium, but why does it feel like there's an endless amount of water here?",
  ui_story_5086_50860801_15_dialog_content = "Looks like this room won't last much longer either.",
  ui_story_5086_50860801_16_dialog_content = "So what should we do now?",
  ui_story_5086_50860801_17_dialog_content = "I think we need to find a way to regroup with everyone first.",
  ui_story_5086_50860801_18_dialog_content = "Help—!",
  ui_story_5086_50860801_19_dialog_content = "Someone's in trouble!",
  ui_story_5086_50860801_20_dialog_content = "Don't worry, Super Sadie Swashbuckler 666 is on the way!",
  ui_story_5086_50860801_21_dialog_content = "Wait—",
  ui_story_5086_50860801_22_dialog_content = "We'll go with you.",
  ui_story_5086_50860801_23_dialog_content = "Over there! Look!",
  ui_story_5086_50860801_24_dialog_content = "<color=#e8d9bb>The water in the hallway is already at waist height. A group of visitors cry out for help from atop a floating piece of wood.</color>",
  ui_story_5086_50860801_25_dialog_content = "<color=#e8d9bb>Swimming towards them is a massive shark—</color>",
  ui_story_5086_50860801_26_dialog_content = "Get lost, you big blowhard!",
  ui_story_5086_50860801_27_dialog_content = "<color=#e8d9bb>Surprisingly, Sadie's attack forces the shark to retreat a few feet away.</color>",
  ui_story_5086_50860801_28_dialog_content = "Don't worry, a swashbuckler always protects anyone in need!",
  ui_story_5086_50860801_29_dialog_content = "Here, PlayerName! Grab onto this!",
  ui_story_5086_50860801_30_dialog_content = "A fishing net? Where did you get ahold of this?",
  ui_story_5086_50860801_31_dialog_content = "I nearly got tangled in it on the way here. I thought it might come in handy later, so I brought it along.",
  ui_story_5086_50860801_32_dialog_content = "Let's use it!",
  ui_story_5086_50860801_33_dialog_content = "Think we can pull this off together, Sadie?",
  ui_story_5086_50860801_34_dialog_content = "Of course! A swashbuckler never surrenders!",
  ui_story_5086_50860801_35_dialog_content = "Then on my count—",
  ui_story_5086_50860801_36_dialog_content = "Three.",
  ui_story_5086_50860801_37_dialog_content = "<color=#e8d9bb>Sadie raises her baseball bat.</color>",
  ui_story_5086_50860801_38_dialog_content = "Two.",
  ui_story_5086_50860801_39_dialog_content = "<color=#e8d9bb>Goldie and I creep forward quietly.</color>",
  ui_story_5086_50860801_40_dialog_content = "One!",
  ui_story_5086_50860801_41_dialog_content = "<size=50>You're outta here—!</size>",
  ui_story_5086_50860801_42_dialog_content = "<color=#e8d9bb>The shark lands perfectly inside of the waiting net.</color>",
  ui_story_5086_50860801_43_dialog_content = "Well done, everyone.",
  ui_story_5086_50860801_44_dialog_content = "You hardly broke a sweat just now, Goldie... Am I really that out of shape?",
  ui_story_5086_50860801_45_dialog_content = "Heehee!",
  ui_story_5086_50860801_46_dialog_content = "Come on Sadie, let's get going—!",
  ui_story_5086_50860801_47_dialog_content = "<color=#e8d9bb>Suddenly, an enormous shadow appears in the water behind Sadie.</color>",
  ui_story_5086_50860801_48_dialog_content = "Get out of there, Sadie!",
  ui_story_5086_50860801_49_dialog_content = "Roar!!!",
  ui_story_5086_50860801_50_dialog_content = "!",
  ui_story_5086_50860801_51_dialog_content = "(I-It's too late...)",
  ui_story_5086_50860801_52_dialog_content = "<size=50>Swift Verdict.</size>",
  ui_story_5086_50860801_53_dialog_content = "<size=50>Peerless Manae!</size>",
  ui_story_5086_50860801_54_dialog_content = "Our apologies for taking so long, everybody.",
  ui_story_5086_50860801_55_dialog_content = "I merely stepped away to fetch Sanae, but it seems a number of vile creatures have appeared in our absence.",
  ui_story_5086_50860801_56_dialog_content = "<color=#e8d9bb>Minos stands perfectly poised on top of a ribbon in midair and delivers a courteous bow.</color>",
  ui_story_5086_50860801_57_dialog_content = "<color=#e8d9bb>Under his left arm is a very distraught-looking Sanae.</color>",
  ui_story_5086_50860801_58_dialog_content = "Um... P-Please forgive me! I didn't mean to sleep through everything!",
  ui_story_5086_50860801_59_dialog_content = "B-But now that I'm here, I'll do everything I can to make things right!",
  ui_story_5086_50860801_60_dialog_content = "That's much better, Sanae. Now get started, if you please.",
  ui_story_5086_50860801_61_dialog_content = "Huh?",
  ui_story_5086_50860801_62_dialog_content = "Look out, everyone! More Eclipsites are on the way!",
  ui_story_5086_50860802_1_dialog_content = "Graaah...",
  ui_story_5086_50860802_2_dialog_content = "It's finally over... Just how many Eclipsites are hiding underwater?",
  ui_story_5086_50860802_3_dialog_content = "It may not prove your theory of hidden rooms in the aquarium, but this is still a compelling piece of evidence.",
  ui_story_5086_50860802_4_dialog_content = "Is this really the time for that, Minos?",
  ui_story_5086_50860802_5_dialog_content = "Absolutely. Until the truth becomes clear, we mustn't lose sight of our investigation.",
  ui_story_5086_50860802_6_dialog_content = "Hey!",
  ui_story_5086_50860802_7_dialog_content = "I don't know what you guys are talking about, but that shark is heading straight for us!",
  ui_story_5086_50860802_8_dialog_content = "<color=#e8d9bb>The sound of the fishing net snapping fills the hallway as the shark breaks free from its restraints!</color>",
  ui_story_5086_50860802_9_dialog_content = "<color=#e8d9bb>Further away, more and more dangerous-looking shadows appear under the water's surface.</color>",
  ui_story_5086_50860802_10_dialog_content = "Behind us! And there are lots more of them!",
  ui_story_5086_50860802_11_dialog_content = "We're gonna get eaten alive!!!",
  ui_story_5086_50860802_12_dialog_content = "... Does everyone still have enough strength to fight?",
  ui_story_5086_50860802_13_dialog_content = "I'm pretty tired, but fighting until the bitter end is the only way to go out.",
  ui_story_5086_50860802_14_dialog_content = "As long as a single fan is present, an idol can never show even a hint of exhaustion!",
  ui_story_5086_50860802_15_dialog_content = "Maids and butlers are no different. However...",
  ui_story_5086_50860802_16_dialog_content = "<color=#e8d9bb>The familiar sound of a conch rings out.</color>",
  ui_story_5086_50860802_17_dialog_content = "<color=#e8d9bb>The rampaging shark turns abruptly and swims in the direction of the music.</color>",
  ui_story_5086_50860802_18_dialog_content = "It appears we can lower our weapons now.",
  ui_story_5086_50860802_19_dialog_content = "Let's follow it.",
  ui_story_5086_50860802_20_dialog_content = "<color=#e8d9bb>Reflected by countless pieces of shattered glass, a hazy, shimmering light fills the entirety of the aquarium.</color>",
  ui_story_5086_50860802_21_dialog_content = "<color=#e8d9bb>Maya's blurry figure can be seen standing at the other end of the darkened hallway.</color>",
  ui_story_5086_50860802_22_dialog_content = "<color=#e8d9bb>Entranced by the conch's beautiful melody, countless aquatic creatures of various shapes and sizes swim towards her.</color>",
  ui_story_5086_50860802_23_dialog_content = "Maya—",
  ui_story_5086_50860802_24_dialog_content = "Stay where you are!",
  ui_story_5086_50860802_25_dialog_content = "Miss Stellandine? And Froude, and the rest of the visitors... Thank goodness you're all okay!",
  ui_story_5086_50860802_26_dialog_content = "You call this \"okay\"?! Didn't you see that girl command all of those fish to attack us?!",
  ui_story_5086_50860802_27_dialog_content = "We'd be fish bait right now if the aquarium's owner weren't here to protect us!",
  ui_story_5086_50860802_28_dialog_content = "The missing person from before was probably that girl's victim, too! If you guys think you're so tough, go deal with her right now!",
  ui_story_5086_50860802_29_dialog_content = "Huh?",
  ui_story_5086_50860802_30_dialog_content = "Of course not...",
  ui_story_5086_50860802_31_dialog_content = "She's trying to escape!",
  ui_story_5086_50860802_32_dialog_content = "...",
  ui_story_5086_50860802_33_dialog_content = "Wait, Maya!",
  ui_story_5086_50860802_34_dialog_content = "Argh, I can't move fast enough in the water! I can't catch up—",
  ui_story_5086_50860802_35_dialog_content = "Leave this to me, Mr. PlayerName. Please watch over the others on my end.",
  ui_story_5086_50860802_36_dialog_content = "<color=#e8d9bb>Minos leaps deftly across the floating debris and goes after Maya.</color>",
  ui_story_5086_50860802_37_dialog_content = "... We can't keep staying here. We need to find a safe place for everyone to take shelter.",
  ui_story_5086_50860802_38_dialog_content = "The water still hasn't reached the second floor. We should try to make our way up there.",
  ui_story_5086_50860802_39_dialog_content = "I'm not going with you people! I have to go find Miss Maya!",
  ui_story_5086_50860802_40_dialog_content = "I'm sorry, little one, but we should really discuss this once everybody is safe.",
  ui_story_5086_50860802_41_dialog_content = "No way! You're a bad lady, so keep your hands off of me!",
  ui_story_5086_50860802_42_dialog_content = "Allow me, Miss Stellandine.",
  ui_story_5086_50860802_43_dialog_content = "I know you're upset, little guy, but you have to stay positive in times like this! If you don't smile when things get tough, you won't stay happy for very long!",
  ui_story_5086_50860802_44_dialog_content = "B-But they said all those mean things about Miss Maya!",
  ui_story_5086_50860802_45_dialog_content = "I know, and that's no way to talk about anyone. But you don't agree with them at all, do you?",
  ui_story_5086_50860802_46_dialog_content = "H-Huh? Do you... Believe me?",
  ui_story_5086_50860802_47_dialog_content = "Hmm... I'm not sure, since I just met her for the first time today.",
  ui_story_5086_50860802_48_dialog_content = "So, Froude, please tell me and everyone else why Maya would never do anything bad.",
  ui_story_5086_50860802_49_dialog_content = "Okay! Okay!",
  ui_story_5086_50860802_50_dialog_content = "Looks like everything's fine now. Let's go, Miss Stellandine.",
  ui_story_5086_50860802_51_dialog_content = "I'll try to keep my distance.",
  ui_story_5086_50860802_52_dialog_content = "The kid seems to dislike me.",
  ui_story_5086_50860802_53_dialog_content = "Uh... Maybe he's just anxious because he's close to Maya.",
  ui_story_5086_50860802_54_dialog_content = "Actually, it's the same for me.",
  ui_story_5086_50860802_55_dialog_content = "I really can't believe that Maya is a bad person.",
  ui_story_5086_50860802_56_dialog_content = "She's just... A bit clumsy.",
  ui_story_5086_50860802_57_dialog_content = "But she's a good girl, no doubt about it.",
  ui_story_5086_50860802_58_dialog_content = "There must be some misunderstanding, but hopefully Minos can set things straight!",
  ui_story_5086_50860802_59_dialog_content = "Um... Miss Stellandine...",
  ui_story_5086_50860802_60_dialog_content = "Is this the only way to reach the second floor?",
  ui_story_5086_50860802_61_dialog_content = "Yes. Why do you ask?",
  ui_story_5086_50860802_62_dialog_content = "But... Goldie and the others have disappeared.",
  ui_story_5086_50860802_63_dialog_content = "And our surroundings... It looks like everything's been distorted somehow.",
  ui_story_5086_50860802_64_dialog_content = "That's very concerning, yes...",
  ui_story_5086_50860802_65_dialog_content = "Are you alright? You look really pale.",
  ui_story_5086_50860802_66_dialog_content = "To tell the truth... I don't feel so well...",
  ui_story_5086_50860802_67_dialog_content = "But I'll be fine. Please go on without me...",
  ui_story_5086_50860802_68_dialog_content = "How could I do that?! Come on! I may not be the strongest, but I can definitely help you walk.",
  ui_story_5086_50860802_69_dialog_content = "!",
  ui_story_5086_50860802_70_dialog_content = "... What is it?",
  ui_story_5086_50860802_71_dialog_content = "I think... I sense an Eclipsite...",
  ui_story_5086_50860901_1_dialog_content = "La-la-la♪",
  ui_story_5086_50860901_2_dialog_content = "Um... Miss Goldie?",
  ui_story_5086_50860901_3_dialog_content = "Have you discovered anything?",
  ui_story_5086_50860901_4_dialog_content = "I have! The second floor isn't flooded, and no one's quarreling either.",
  ui_story_5086_50860901_5_dialog_content = "We just need to locate the exit to get out of here!",
  ui_story_5086_50860901_6_dialog_content = "No, I'm not talking about that...",
  ui_story_5086_50860901_7_dialog_content = "I guess she's trying to say that all the people who were following us have disappeared.",
  ui_story_5086_50860901_8_dialog_content = "Huh?",
  ui_story_5086_50860901_9_dialog_content = "They're really gone! Hello? PlayerName? Froude? Miss Stellandine?!",
  ui_story_5086_50860901_10_dialog_content = "The only response is an echo.",
  ui_story_5086_50860901_11_dialog_content = "This place... Something about it feels different now...",
  ui_story_5086_50860901_12_dialog_content = "The atmosphere... It's so intense now.",
  ui_story_5086_50860901_13_dialog_content = "I know, right? It's like the sudden change in the art style.",
  ui_story_5086_50860901_14_dialog_content = "There are super-creepy images on the glass, and it feels like a monster could jump out at us at any second.",
  ui_story_5086_50860901_15_dialog_content = "<size=50>Eeek!</size>",
  ui_story_5086_50860901_16_dialog_content = "Stop scaring yourselves like that! No matter how terrifying it may seem, it's still just an aquarium.",
  ui_story_5086_50860901_17_dialog_content = "Don't you remember what Miss Maya said? This is where we experience dreams, and once you realize that, there's nothing to fear.",
  ui_story_5086_50860901_18_dialog_content = "This place is more like a nightmare now.",
  ui_story_5086_50860901_19_dialog_content = "Let's sing then.",
  ui_story_5086_50860901_20_dialog_content = "Singing from the heart has the power to pierce through the darkness and nightmares!",
  ui_story_5086_50860901_21_dialog_content = "I was truly overjoyed to read that in the papers after the last concert!",
  ui_story_5086_50860901_22_dialog_content = "Anyway, let's start gathering up our lost companions.",
  ui_story_5086_50860901_23_dialog_content = "P-Please wait...",
  ui_story_5086_50860901_24_dialog_content = "Over there... Eclipsites!",
  ui_story_5086_50860901_25_dialog_content = "Just hang on a little longer! That Eclipsite is definitely somewhere nearby!",
  ui_story_5086_50860901_26_dialog_content = "Okay... Thank you...",
  ui_story_5086_50860901_27_dialog_content = "This place is different from before. It feels like a maze now... Ah!",
  ui_story_5086_50860901_28_dialog_content = "Look! It's Sanae and the others!",
  ui_story_5086_50860901_29_dialog_content = "We...",
  ui_story_5086_50860901_30_dialog_content = "<size=50>Peerless Manae!</size>",
  ui_story_5086_50860901_31_dialog_content = "?!",
  ui_story_5086_50860901_32_dialog_content = "Ah—",
  ui_story_5086_50860901_33_dialog_content = "Miss Stellandine!",
  ui_story_5086_50860901_34_dialog_content = "Wait up, Sanae! It's us!",
  ui_story_5086_50860901_35_dialog_content = "Huh? H-How could this be...",
  ui_story_5086_50860901_36_dialog_content = "It hurts...",
  ui_story_5086_50860901_37_dialog_content = "H-H-How could I attack you like that?! I'm so sorry! I-I thought you...",
  ui_story_5086_50860901_38_dialog_content = "A-Are you alright?",
  ui_story_5086_50860901_39_dialog_content = "... Please don't touch me.",
  ui_story_5086_50860901_40_dialog_content = "Boo-hoo... I'm really, truly sorry! I mistook you for an Eclipsite just now...",
  ui_story_5086_50860901_41_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_42_dialog_content = "That's the sound of Maya's conch! She's close!",
  ui_story_5086_50860901_43_dialog_content = "I... Uh...",
  ui_story_5086_50860901_44_dialog_content = "P-Please stay still for a while. I-I...",
  ui_story_5086_50860901_45_dialog_content = "AH! Sadie and Miss Goldie are gone... They must have been attracted by the sound.",
  ui_story_5086_50860901_46_dialog_content = "I'll stay here and protect Miss Stellandine. Please go help them, PlayerName!",
  ui_story_5086_50860901_47_dialog_content = "Nngh... You go as well, and take care of Maya.",
  ui_story_5086_50860901_48_dialog_content = "I'm heading over then!",
  ui_story_5086_50860901_49_dialog_content = "(The sound of the conch feels completely different.)",
  ui_story_5086_50860901_50_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_51_dialog_content = "(Urgh... Just hearing that sound makes my mind go hazy.)",
  ui_story_5086_50860901_52_dialog_content = "(Maya, what are you...)",
  ui_story_5086_50860901_53_dialog_content = "!",
  ui_story_5086_50860901_54_dialog_content = "You truly are no different than the heroes of classical dramas, my friend.",
  ui_story_5086_50860901_55_dialog_content = "When you put it that way, it makes me think you really need my help again.",
  ui_story_5086_50860901_56_dialog_content = "It is as you suspect, yes.",
  ui_story_5086_50860901_57_dialog_content = "It shames me to admit it, but I could barely do battle while resisting the effects of her conch's illusion.",
  ui_story_5086_50860901_58_dialog_content = "<color=#e8d9bb>Fwooo—</color>",
  ui_story_5086_50860901_59_dialog_content = "Maya!",
  ui_story_5086_50860901_60_dialog_content = "...",
  ui_story_5086_50860901_61_dialog_content = "Don't worry, Minos! I'll protect your mind while you fight!",
  ui_story_5086_50860901_62_dialog_content = "I trust your ability and judgment, so just focus on getting close to Maya!",
  ui_story_5086_50860901_63_option_content = "Psychic Scan!",
  ui_story_5086_50860901_64_dialog_content = "<color=#e8d9bb>Graw!</color>",
  ui_story_5086_50860901_65_dialog_content = "I can hardly afford to disappoint my comrade now that he has placed so much faith in me. Forgive me, Miss Maya, but I must ask for your cooperation now.",
  ui_story_5086_50860901_66_dialog_content = "!",
  ui_story_5086_50860901_67_dialog_content = "Stay back!",
  ui_story_5086_50860901_68_dialog_content = "Please lower the conch, and I assure you that no harm will come to you.",
  ui_story_5086_50860901_69_dialog_content = "I... I don't understand what's happening right now... But I can't!",
  ui_story_5086_50860901_70_dialog_content = "Urgh...",
  ui_story_5086_50860901_71_dialog_content = "The psychic attacks suddenly got stronger— Argh, my head!",
  ui_story_5086_50860901_72_dialog_content = "It appears I must fight seriously now.",
  ui_story_5086_50860901_73_dialog_content = "Forgive me, Miss Maya. I will offer you a proper apology once this is over.",
  ui_story_5086_50860901_74_dialog_content = "<size=50>Swift Verdict!</size>",
  ui_story_5086_50860901_75_dialog_content = "Wait... Don't!",
  ui_story_5086_50860901_76_dialog_content = "I can't bleed! I'm not supposed to!",
  ui_story_5086_50860901_77_dialog_content = "Please help me—",
  ui_story_5086_50860901_78_dialog_content = "<color=#FFB400>Ancestor!</color>",
  ui_story_5086_50860901_79_dialog_content = "<color=#e8d9bb>Ugh!</color>",
  ui_story_5086_50860901_80_dialog_content = "<color=#e8d9bb>Suddenly, we hear a long and clear chant.</color>",
  ui_story_5086_50860901_81_dialog_content = "<color=#e8d9bb>Boundless and substantial yet fleeting and ethereal. All contradictions are simultaneously validated in this single moment.</color>",
  ui_story_5086_50860901_82_dialog_content = "<color=#e8d9bb>Countless colors flicker and converge behind Maya.</color>",
  ui_story_5086_50860901_83_dialog_content = "How magnificent...",
  ui_story_5086_50860901_84_dialog_content = "<color=#e8d9bb>I had never laid eyes on such a fantastical creature, yet as soon as I did, I somehow understood it.</color>",
  ui_story_5086_50860901_85_dialog_content = "<color=#e8d9bb>It is something born of fantasies, dreams, and the endless projection of thoughts...</color>",
  ui_story_5086_50860901_86_dialog_content = "<color=#e8d9bb>An ancient phantom that could shatter reality with ease.</color>",
  ui_story_5086_50860901_87_dialog_content = "<color=#e8d9bb>With a single breath, this ephemeral dragon...</color>",
  ui_story_5086_50860901_88_dialog_content = "<color=#e8d9bb>... could reshape all of existence.</color>",
  ui_story_5086_50860901_89_dialog_content = "Is this an illusion? Or have we really arrived somewhere else?",
  ui_story_5086_50860901_90_dialog_content = "This world must be Miss Maya's creation, a place where <color=#FFB400>illusions</color> and <color=#FFB400>reality</color> are one and the same.",
  ui_story_5086_50860901_91_dialog_content = "Please exercise caution.",
  ui_story_5086_50860901_92_dialog_content = "I doubt she created this space simply for us to enjoy the views.",
  ui_story_5086_50860901_93_dialog_content = "I doubt she created this space for us to take in the sights.",
  ui_story_5086_50860902_1_dialog_content = "Good job, Minos.",
  ui_story_5086_50860902_2_dialog_content = "... Minos?",
  ui_story_5086_50860902_3_dialog_content = "Gone again...",
  ui_story_5086_50860902_4_dialog_content = "Meow!",
  ui_story_5086_50860902_5_dialog_content = "Huh? A cat?",
  ui_story_5086_50860902_6_dialog_content = "Meow! Meow!",
  ui_story_5086_50860902_7_dialog_content = "Are you trying to get me to follow you?",
  ui_story_5086_50860902_8_dialog_content = "Meow!",
  ui_story_5086_50860902_9_dialog_content = "Fine, I don't know where to go anyway.",
  ui_story_5086_50860902_10_dialog_content = "<color=#e8d9bb>Splash—</color>",
  ui_story_5086_50860902_11_dialog_content = "Ugh!",
  ui_story_5086_50860902_12_dialog_content = "Ack... Glub, glub, glub...",
  ui_story_5086_50860902_13_dialog_content = "He... Glub, glub, glub... Help...",
  ui_story_5086_50860902_14_dialog_content = "It's you...",
  ui_story_5086_50860902_15_dialog_content = "<color=#e8d9bb>Splash.</color>",
  ui_story_5086_50860902_16_dialog_content = "Pffft! Cough, cough, cough...",
  ui_story_5086_50860902_17_dialog_content = "I... I'm saved! Thank you...",
  ui_story_5086_50860902_18_dialog_content = "The ground just vanished beneath me, and I plunged into the sea. I thought I was a goner.",
  ui_story_5086_50860902_19_dialog_content = "Wh-What are you doing here, Miss Stellandine?",
  ui_story_5086_50860902_20_dialog_content = "I heard the sound of a conch not long after you left, and the next thing I knew, I was here.",
  ui_story_5086_50860902_21_dialog_content = "With nothing but the ocean around me, all I could do was wait on this beach. That's when I saw you fall into the water.",
  ui_story_5086_50860902_22_dialog_content = "I was led to a strange place by a cat, then rescued after falling into the ocean.",
  ui_story_5086_50860902_23_dialog_content = "It's almost like a fairy tale.",
  ui_story_5086_50860902_24_dialog_content = "Maybe... this is a fairy tale.",
  ui_story_5086_50860902_25_dialog_content = "It appears the power of Maya's bloodline extends far beyond calming the hearts of others. It can create powerful illusions as well.",
  ui_story_5086_50860902_26_dialog_content = "This may very well be the setting of another fairy tale.",
  ui_story_5086_50860902_27_dialog_content = "Still, I never imagined she would use her powers against others like this...",
  ui_story_5086_50860902_28_dialog_content = "There may be more to it than meets the eye.",
  ui_story_5086_50860902_29_dialog_content = "When I saw Maya earlier, she seemed to be worried about something.",
  ui_story_5086_50860902_30_dialog_content = "Ah! Ah-ah-aaaaaah!",
  ui_story_5086_50860902_31_dialog_content = "I think I hear someone singing.",
  ui_story_5086_50860902_32_dialog_content = "Look over there, Miss Stellandine! Next to the water!",
  ui_story_5086_50860902_33_dialog_content = "That's... The daughter of the ocean...",
  ui_story_5086_50860902_34_dialog_content = "You mean the mermaid from that story? She's beautiful...",
  ui_story_5086_50860902_35_dialog_content = "Hey, there's a ship coming! Could this be the part where the prince and the mermaid first meet?",
  ui_story_5086_50860902_36_dialog_content = "I wonder if that ship can get us out of here? Hey—",
  ui_story_5086_50860902_37_dialog_content = "... This isn't working. It's like the people on the ship can't see us at all.",
  ui_story_5086_50860902_38_dialog_content = "...",
  ui_story_5086_50860902_39_dialog_content = "I guess we just can't beat the mermaid princess in a contest of charm.",
  ui_story_5086_50860902_40_dialog_content = "<color=#e8d9bb>Kaboom!</color>",
  ui_story_5086_50860902_41_dialog_content = "Thunder? And the sky has gone dark too... It's the storm in the story, huh?",
  ui_story_5086_50860902_42_dialog_content = "But the ship is fine, and they've even sailed up to her and tossed down a rope ladder for her...",
  ui_story_5086_50860902_43_dialog_content = "<color=#e8d9bb>Amid the rumbling of thunder, I witness something inconceivable.</color>",
  ui_story_5086_50860902_44_dialog_content = "<color=#e8d9bb>The mermaid stretches out her snow-white hand and pulls her rescuers into the water.</color>",
  ui_story_5086_50860902_45_dialog_content = "<color=#e8d9bb>As screams fill the air, a foul stench rises from the water, which is slowly turning a deep crimson hue.</color>",
  ui_story_5086_50860902_46_dialog_content = "<color=#e8d9bb>When the blood finally reaches the shore, the gruesome scene suddenly disappears.</color>",
  ui_story_5086_50860902_47_dialog_content = "<color=#e8d9bb>Afterward, we find ourselves back in the aquarium.</color>",
  ui_story_5086_50860902_48_dialog_content = "<color=#e8d9bb>But the foul stench seems to linger in the air around us.</color>",
  ui_story_5086_50860902_49_dialog_content = "What was that... Just now...",
  ui_story_5086_50860902_50_dialog_content = "That... That wasn't... That's not how the story goes!",
  ui_story_5086_50860902_51_dialog_content = "... Moya is a pure-hearted child.",
  ui_story_5086_50860902_52_dialog_content = "So pure that she sees, accepts, and loves everything in the world exactly the same.",
  ui_story_5086_50860902_53_dialog_content = "It's possible that what we just saw isn't good or evil in her eyes.",
  ui_story_5086_50860902_54_dialog_content = "So even Eclipsites may somehow become her companions.",
  ui_story_5086_50861001_1_dialog_content = "... We can't stop now.",
  ui_story_5086_50861001_2_dialog_content = "Miss Stellandine, can you stand?",
  ui_story_5086_50861001_3_dialog_content = "Urgh...",
  ui_story_5086_50861001_4_dialog_content = "I can't.",
  ui_story_5086_50861001_5_dialog_content = "Then I'll carry you.",
  ui_story_5086_50861001_6_dialog_content = "What? But you're not doing so well yourself, aren't you?",
  ui_story_5086_50861001_7_dialog_content = "Yeah... kind of...",
  ui_story_5086_50861001_8_dialog_content = "But I have no idea how many Eclipsites are still lurking around us, and I'm sensing a strange presence somewhere close by.",
  ui_story_5086_50861001_9_dialog_content = "I can't leave you here either.",
  ui_story_5086_50861001_10_dialog_content = "Just hold on to me, and let me know if it hurts too much to keep going.",
  ui_story_5086_50861001_11_dialog_content = "You're such a kind soul, PlayerName.",
  ui_story_5086_50861001_12_dialog_content = "I'm sorry for getting you involved in this mess.",
  ui_story_5086_50861001_13_dialog_content = "It's fine, I'm used to this sort of thing. Besides, I'm sure you want to preserve the aquarium more than anyone else, right?",
  ui_story_5086_50861001_14_dialog_content = "Yes. I'd rather not...",
  ui_story_5086_50861001_15_dialog_content = "Roar!",
  ui_story_5086_50861001_16_dialog_content = "!",
  ui_story_5086_50861001_17_dialog_content = "Eclipsites! We'll have to go another way.",
  ui_story_5086_50861001_18_dialog_content = "Do you know where we are right now, Miss Stellandine?",
  ui_story_5086_50861001_19_dialog_content = "I'm sorry, but it seems the aquarium has been completely warped.",
  ui_story_5086_50861001_20_dialog_content = "The order of the rooms has been mixed up, so I can't even discern the direction in which we're heading.",
  ui_story_5086_50861001_21_dialog_content = "Guess we'll just have to take our chances.",
  ui_story_5086_50861001_22_dialog_content = "Look over there... Who is that?",
  ui_story_5086_50861001_23_dialog_content = "Hello, I'm—",
  ui_story_5086_50861001_24_dialog_content = "H-Help me!",
  ui_story_5086_50861001_25_dialog_content = "Huh? Wait, why are you running away?",
  ui_story_5086_50861001_26_dialog_content = "Don't kill me—",
  ui_story_5086_50861001_27_dialog_content = "What's going on? Is he being chased? Urgh...",
  ui_story_5086_50861001_28_dialog_content = "Miss Stellandine, do you smell something strange?",
  ui_story_5086_50861001_29_dialog_content = "Something strange, you say...?",
  ui_story_5086_50861001_30_dialog_content = "I thought it was just an aftereffect of that mermaid illusion earlier, but I can still smell it now.",
  ui_story_5086_50861001_31_dialog_content = "It's a rotten smell, and it seems to be getting closer...",
  ui_story_5086_50861001_32_dialog_content = "Huff... Huff...",
  ui_story_5086_50861001_33_dialog_content = "Huh? Who's there?",
  ui_story_5086_50861001_34_dialog_content = "... Sanae? Y-You're covered in blood! Did you get hurt?!",
  ui_story_5086_50861001_35_dialog_content = "Please tell me you're okay!!",
  ui_story_5086_50861001_36_dialog_content = "Eeeek!",
  ui_story_5086_50861001_37_dialog_content = "What's wrong, Sanae?! It's just us!",
  ui_story_5086_50861001_38_dialog_content = "Roar!",
  ui_story_5086_50861001_39_dialog_content = "Whoa!",
  ui_story_5086_50861001_40_dialog_content = "Has this thing been following us all this time?!",
  ui_story_5086_50861001_41_dialog_content = "Sorry Miss Stellandine, but I have to put you down. Please pass me that stick in the corner and stay with Sanae.",
  ui_story_5086_50861001_42_dialog_content = "Forget about me... Just run away.",
  ui_story_5086_50861001_43_dialog_content = "No way! I'm staying here to fight!",
  ui_story_5086_50861001_44_dialog_content = "Just because I'm usually standing behind everyone doesn't mean I don't know how to protect my friends!",
  ui_story_5086_50861001_45_dialog_content = "Roar!",
  ui_story_5086_50861001_46_dialog_content = "Hah—",
  ui_story_5086_50861001_47_dialog_content = "<color=#e8d9bb>Whack!</color>",
  ui_story_5086_50861001_48_dialog_content = "Graaah—",
  ui_story_5086_50861001_49_dialog_content = "Huh? No way... Did I just one-shot an Eclipsite? Me?!",
  ui_story_5086_50861001_50_dialog_content = "You're welcome.",
  ui_story_5086_50861001_51_dialog_content = "Sadie! So you're the one who took it out.",
  ui_story_5086_50861001_52_dialog_content = "Don't lose focus. There's plenty more where that one came from.",
  ui_story_5086_50861001_53_dialog_content = "<size=50>You're outta here!</size>",
  ui_story_5086_50861001_54_dialog_content = "I'll help out too! Hya—",
  ui_story_5086_50861001_55_dialog_content = "\"Just because I'm usually standing behind everyone doesn't mean I don't know how to protect my friends!\" That was such a cool line!",
  ui_story_5086_50861001_56_dialog_content = "Goldie! Sadie! You two showed up right in the nick of time!",
  ui_story_5086_50861001_57_dialog_content = "Idols and swashbucklers should never be late, you know!",
  ui_story_5086_50861001_58_dialog_content = "Now it's our time to shine!",
  ui_story_5086_50861002_1_dialog_content = "Graaah—",
  ui_story_5086_50861002_2_dialog_content = "Thank you for listening!",
  ui_story_5086_50861002_3_dialog_content = "We're safe now. Thank goodness you made it in time.",
  ui_story_5086_50861002_4_dialog_content = "I couldn't have done it without those visitors.",
  ui_story_5086_50861002_5_dialog_content = "They told us there were scary Eclipsites lurking in this direction, so we came to take a look.",
  ui_story_5086_50861002_6_dialog_content = "It must've been that guy who ran off just now. He took off as soon as he saw us...",
  ui_story_5086_50861002_7_dialog_content = "Have you been alone all this time, PlayerName?",
  ui_story_5086_50861002_8_dialog_content = "I've been with Sanae and Miss Stellandine. I made them hide over there... Huh?",
  ui_story_5086_50861002_9_dialog_content = "Where are they? All I see is...",
  ui_story_5086_50861002_10_dialog_content = "A puddle of blood?",
  ui_story_5086_50861002_11_dialog_content = "<color=#e8d9bb>Click.</color>",
  ui_story_5086_50861002_12_dialog_content = "Um... Miss Stellandine?",
  ui_story_5086_50861002_13_dialog_content = "Don't worry, I'll go lock the door.",
  ui_story_5086_50861002_14_dialog_content = "We're the only ones here now.",
  ui_story_5086_50861002_15_dialog_content = "So we're safe.",
  ui_story_5086_50861002_16_dialog_content = "Are you certain, Miss Stellandine?",
  ui_story_5086_50861002_17_dialog_content = "Of course.",
  ui_story_5086_50861002_18_dialog_content = "Then why...",
  ui_story_5086_50861002_19_dialog_content = "... do you look like...",
  ui_story_5086_50861002_20_dialog_content = "... an Eclipsite?",
  ui_story_5086_50861002_21_dialog_content = "...",
  ui_story_5086_50861002_22_dialog_content = "Could it be that Sanae and Miss Stellandine...",
  ui_story_5086_50861002_23_dialog_content = "We can't rush to conclusions until we find them!",
  ui_story_5086_50861002_24_dialog_content = "Check every corner of the room. People don't just disappear without a trace, so there must be some clues.",
  ui_story_5086_50861002_25_dialog_content = "Goldie's right! I'll search the hallway over there.",
  ui_story_5086_50861002_26_dialog_content = "PlayerName! Wait!",
  ui_story_5086_50861002_27_dialog_content = "Wait, your back... There's something sticky on it. What are these... Shards?",
  ui_story_5086_50861002_28_dialog_content = "It looks a little gross... These shards almost feel like flesh...",
  ui_story_5086_50861002_29_dialog_content = "So when the sound drew everyone away, only you and I stayed behind...",
  ui_story_5086_50861002_30_dialog_content = "Were you the one who attacked me from behind?",
  ui_story_5086_50861002_31_dialog_content = "That's right.",
  ui_story_5086_50861002_32_dialog_content = "... You were controlling all of those Eclipsites too, Miss Stellandine?",
  ui_story_5086_50861002_33_dialog_content = "So you figured it out, huh?",
  ui_story_5086_50861002_34_dialog_content = "Of course. Because I'm quite skilled in manipulation.",
  ui_story_5086_50861002_35_dialog_content = "Those Eclipsites occasionally act like... puppets.",
  ui_story_5086_50861002_36_dialog_content = "That's quite surprising. But... it's too late now.",
  ui_story_5086_50861002_37_dialog_content = "I'm... really starving.",
  ui_story_5086_50861002_38_dialog_content = "I'm sorry, it's been so long since I've had a normal meal.",
  ui_story_5086_50861002_39_dialog_content = "I don't want this either...",
  ui_story_5086_50861002_40_dialog_content = "But I just can't stand it anymore...",
  ui_story_5086_50861002_41_dialog_content = "I have a favor to ask. Please... be my food!",
  ui_story_5086_50861002_42_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5086_50861002_43_dialog_content = "Why must you resist? Why won't anything go my way?!",
  ui_story_5086_50861002_44_dialog_content = "Forgive me, but I'm a maid of the Andersen family.",
  ui_story_5086_50861002_45_dialog_content = "I haven't completed the task Mr. Minos entrusted to me. Not to mention Miss Nina is awaiting my return.",
  ui_story_5086_50861002_46_dialog_content = "I-I still have friends I want to see again, so please...",
  ui_story_5086_50861002_47_dialog_content = "I cannot allow myself to be eaten by you.",
  ui_story_5086_50861002_48_dialog_content = "If you're that hungry, try eating yourself, darn monster!",
  ui_story_5086_50861002_49_dialog_content = "<color=#e8d9bb>Boom—</color>",
  ui_story_5086_50861002_50_dialog_content = "What is this crazy strength?! It's like I'm facing a completely different person!",
  ui_story_5086_50861002_51_dialog_content = "But no matter how powerful you are, you're still injured.",
  ui_story_5086_50861002_52_dialog_content = "Attack!",
  ui_story_5086_50861002_53_dialog_content = "Roar!",
  ui_story_5086_50861002_54_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5086_50861002_55_dialog_content = "<color=#e8d9bb>The Eclipsites charge into the room but are thrown out just a moment later—Of course, none of them are breathing now.</color>",
  ui_story_5086_50861002_56_dialog_content = "What?!",
  ui_story_5086_50861002_57_dialog_content = "Under ordinary circumstances, guests should treat their host with the utmost respect.",
  ui_story_5086_50861002_58_dialog_content = "Since you attacked my family's maid, you left me no choice.",
  ui_story_5086_50861002_59_dialog_content = "For the sake of the Andersen family's honor, and to quell my own rage...",
  ui_story_5086_50861002_60_dialog_content = "I must depart from my usual politeness.",
  ui_story_5086_50861002_61_dialog_content = "How meddlesome...",
  ui_story_5086_50861002_62_dialog_content = "Roar!",
  ui_story_5086_50861002_63_dialog_content = "Stand aside, you filthy beast.",
  ui_story_5086_50861002_64_dialog_content = "Humph, such cowardly creatures.",
  ui_story_5086_50861100_1_dialog_content = "Sanae—where are you—",
  ui_story_5086_50861100_2_dialog_content = "If you can hear us, say something!",
  ui_story_5086_50861100_3_dialog_content = "Sanae—",
  ui_story_5086_50861100_4_dialog_content = "Miss Moya! Don't go!",
  ui_story_5086_50861100_5_dialog_content = "That voice...!",
  ui_story_5086_50861100_6_dialog_content = "Froude! Maya!",
  ui_story_5086_50861100_7_dialog_content = "Oh, PlayerName...",
  ui_story_5086_50861100_8_dialog_content = "You'll be safe here, Froude. I'm sorry, but I have to go now.",
  ui_story_5086_50861100_9_dialog_content = "I won't do it! I won't let you go!",
  ui_story_5086_50861100_10_dialog_content = "Did you find her? The girl who was controlling those sharks...",
  ui_story_5086_50861100_11_dialog_content = "Don't let her get away!",
  ui_story_5086_50861100_12_dialog_content = "...",
  ui_story_5086_50861100_13_dialog_content = "Please calm down, everyone! Maya is—",
  ui_story_5086_50861100_14_dialog_content = "You guys don't know a thing about her! You're all a bunch of idiots!",
  ui_story_5086_50861100_15_dialog_content = "Froude...",
  ui_story_5086_50861100_16_dialog_content = "Miss Maya's the biggest fool of them all! She doesn't even know to look out for herself!",
  ui_story_5086_50861100_17_dialog_content = "She never did anything wrong! I'm sure she wants to catch the bad guy too!",
  ui_story_5086_50861100_18_dialog_content = "Excuse me, but wasn't Maya the one who returned all those fish to their tanks before they bit anyone?",
  ui_story_5086_50861100_19_dialog_content = "I... I'm from around here, and I can vouch for Maya! For the last few years, all she's done is help people all over town!",
  ui_story_5086_50861100_20_dialog_content = "I don't think she could've hurt anybody.",
  ui_story_5086_50861100_21_dialog_content = "Hey! What's the matter with you people?!",
  ui_story_5086_50861100_22_dialog_content = "Are you seriously standing up for her at a time like this?!",
  ui_story_5086_50861100_23_dialog_content = "There is a way to find out once and for all.",
  ui_story_5086_50861100_24_dialog_content = "(Minos... Thanks for the assist.)",
  ui_story_5086_50861100_25_dialog_content = "Not you again, kid... Wait, I remember now! You're the Caelestite!",
  ui_story_5086_50861100_26_dialog_content = "That's right, which means I possess psychic abilities.",
  ui_story_5086_50861100_27_dialog_content = "I remember you were the first one who shook my hand earlier. I already confirmed that you're completely innocent in this case.",
  ui_story_5086_50861100_28_dialog_content = "Th-That is true.",
  ui_story_5086_50861100_29_dialog_content = "There's no denying the kid's talent.",
  ui_story_5086_50861100_30_dialog_content = "That also means I can prove whether or not Maya is innocent right now.",
  ui_story_5086_50861100_31_dialog_content = "I'm sorry, Maya. I know I said I wouldn't use my powers on you if you weren't okay with it.",
  ui_story_5086_50861100_32_dialog_content = "But I'm convinced you're a good person, and many people feel the same way too.",
  ui_story_5086_50861100_33_dialog_content = "Will you let me do that, Maya?",
  ui_story_5086_50861100_34_dialog_content = "But...",
  ui_story_5086_50861100_35_dialog_content = "Listen closely, Maya.",
  ui_story_5086_50861100_36_dialog_content = "What I said just now was just to get those people to back off.",
  ui_story_5086_50861100_37_dialog_content = "So you're not going to read my mind?",
  ui_story_5086_50861100_38_dialog_content = "And I think it's because I believed in you from the very beginning.",
  ui_story_5086_50861100_39_dialog_content = "My psychic powers go both ways. Even I would have a hard time telling a lie when our minds are connected.",
  ui_story_5086_50861100_40_dialog_content = "Which is why I want you to look into my mind first, Maya.",
  ui_story_5086_50861100_41_dialog_content = "If you think I'm worthy of your trust, then please tell me your reasons for doing all of this.",
  ui_story_5086_50861100_42_dialog_content = "Is that... really okay?",
  ui_story_5086_50861100_43_dialog_content = "It's up to you to decide.",
  ui_story_5086_50861100_44_dialog_content = "<color=#e8d9bb>With a small nod, Maya quietly agrees.</color>",
  ui_story_5086_50861100_45_dialog_content = "<color=#e8d9bb>After that, she nervously held out a hand and let our fingertips touch.</color>",
  ui_story_5086_50861100_46_option_content = "Mindlink!",
  ui_story_5086_50861100_47_dialog_content = "<color=#e8d9bb>Under a dazzling sun, flowers turn into butterflies and flutter into the sky to snack on clouds of marshmallows.</color>",
  ui_story_5086_50861100_48_dialog_content = "<color=#e8d9bb>Countless iridescent bubbles drift across the sky, bathing the dream in their whimsical luminescence.</color>",
  ui_story_5086_50861100_49_dialog_content = "(So this is Maya's dream world... It's beautiful.)",
  ui_story_5086_50861100_50_dialog_content = "(But...)",
  ui_story_5086_50861100_51_dialog_content = "(Oh, man! Why am I a frog again?!)",
  ui_story_5086_50861100_52_dialog_content = "Ribbit, ribbit!",
  ui_story_5086_50861100_53_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5086_50861100_54_dialog_content = "(Ouch... Is this ball made of solid gold?!)",
  ui_story_5086_50861100_55_dialog_content = "Sorry about that, Mr. Froggy! Could <color=#FFB400>I</color> have my ball back?",
  ui_story_5086_50861100_56_dialog_content = "Ribbit.",
  ui_story_5086_50861100_57_dialog_content = "Thank you! Muah!",
  ui_story_5086_50861100_58_dialog_content = "!!!",
  ui_story_5086_50861100_59_dialog_content = "Wh-What are you doing, Maya?! You can't just go around kissing people—Hey, I'm back to normal!",
  ui_story_5086_50861100_60_dialog_content = "We can play together if you want! Come on!",
  ui_story_5086_50861100_61_dialog_content = "<color=#e8d9bb>Suddenly, we find ourselves sitting in a golden carriage drawn by six beautiful horses as they charge into an enormous bubble in the sky.</color>",
  ui_story_5086_50861100_62_dialog_content = "This is the candy forest! The ground and trees are made of cakes and cookies, so eat whatever you want.",
  ui_story_5086_50861100_63_dialog_content = "Remember not to eat the gingerbread house in here, or the witch will get angry!",
  ui_story_5086_50861100_64_dialog_content = "<color=#e8d9bb>After eating our fill of sweets, we jump on the back of a snow-white swan and fly into yet another bubble.</color>",
  ui_story_5086_50861100_65_dialog_content = "The palace is hosting a ball, and everyone's invited!",
  ui_story_5086_50861100_66_dialog_content = "If we pick a few vines from the side of the road, we can weave together some outfits that shine brighter than the moon and the stars!",
  ui_story_5086_50861100_67_dialog_content = "<color=#e8d9bb>After changing into our beautiful new clothes, we clamber up a beanstalk and into another bubble.</color>",
  ui_story_5086_50861100_68_dialog_content = "<color=#e8d9bb>Together, we zoomed through countless dream bubbles.</color>",
  ui_story_5086_50861100_69_dialog_content = "<color=#e8d9bb>There were mountains of gold and silver, and even one made of glass...</color>",
  ui_story_5086_50861100_70_dialog_content = "<color=#e8d9bb>We also heard a concerto played by a donkey, a rooster, a cat, and a dog...</color>",
  ui_story_5086_50861100_71_dialog_content = "... And on the other side of the city is an all-knowing doctor.",
  ui_story_5086_50861100_72_dialog_content = "He knows everything about the world, and can answer any question!",
  ui_story_5086_50861100_73_dialog_content = "Really? If we have a chance to see him, I want to ask him something—",
  ui_story_5086_50861100_74_dialog_content = "\"Can you tell me where to find the real Maya?\"",
  ui_story_5086_50861100_75_dialog_content = "...",
  ui_story_5086_50861100_76_dialog_content = "How strange.",
  ui_story_5086_50861100_77_dialog_content = "<color=#e8d9bb>A peculiar light flashes across Maya's eyes.</color>",
  ui_story_5086_50861100_78_dialog_content = "When did you realize it?",
  ui_story_5086_50861100_79_dialog_content = "From the very beginning.",
  ui_story_5086_50861100_80_dialog_content = "When Maya told us her story, I thought it would be okay if someone remembered her existence.",
  ui_story_5086_50861100_81_dialog_content = "Maya said we became friends as soon as we introduced ourselves.",
  ui_story_5086_50861100_82_dialog_content = "So remembering her is the least I could do, right?",
  ui_story_5086_50861100_83_dialog_content = "A notebook shouldn't be the only thing that proves her existence in the world.",
  ui_story_5086_50861100_84_dialog_content = "But then... Who watched over her before she met other people?",
  ui_story_5086_50861100_85_dialog_content = "...",
  ui_story_5086_50861100_86_dialog_content = "In addition to my blood, my descendants also inherit the power to manipulate their surroundings, and even reality itself.",
  ui_story_5086_50861100_87_dialog_content = "With the passage of time, my bloodline has weakened and my descendants can no longer control this power.",
  ui_story_5086_50861100_88_dialog_content = "Not only is she incapable of wielding my power, but our blood connection has also grown tenuous. This causes her to lose her memories and indulge in worlds of fantasy.",
  ui_story_5086_50861100_89_dialog_content = "If the wielder cannot command my power, it will also influence the people around her. Merely seeing or smelling my blood or hearing my voice will trap them in an illusion.",
  ui_story_5086_50861100_90_dialog_content = "So when Maya said she couldn't bleed...",
  ui_story_5086_50861100_91_dialog_content = "However, the situation in the aquarium must have something to do with Maya's power.",
  ui_story_5086_50861100_92_dialog_content = "If you're the Ancestor she mentioned before... Could you tell me what happened here?",
  ui_story_5086_50861100_93_dialog_content = "As I said before, my descendants lack the ability to control dreams.",
  ui_story_5086_50861100_94_dialog_content = "Nevertheless, she has accomplished all of this.",
  ui_story_5086_50861100_95_dialog_content = "If you are truly her friend, then you should know the cause of these events.",
  ui_story_5086_50861100_96_dialog_content = "... You're right.",
  ui_story_5086_50861100_97_dialog_content = "May I ask you one last question?",
  ui_story_5086_50861100_98_dialog_content = "Maya's world is just like a fairy tale. It's a perfect place that has everything a person could ever want.",
  ui_story_5086_50861100_99_dialog_content = "But I noticed something strange while we were flying through all those dreams... Why didn't I see the ocean in any of them?",
  ui_story_5086_50861100_100_dialog_content = "You must have laid eyes on the sea by now.",
  ui_story_5086_50861100_101_dialog_content = "Inside of the nightmare my descendants dare not see.",
  ui_story_5086_50861100_102_dialog_content = "I see... I understand now.",
  ui_story_5086_50861100_103_dialog_content = "Will you answer a question of my own?",
  ui_story_5086_50861100_104_dialog_content = "Of course. Ask me anything.",
  ui_story_5086_50861100_105_dialog_content = "If...",
  ui_story_5086_50861100_106_dialog_content = "Huh? You...",
  ui_story_5086_50861100_107_dialog_content = "If I gave you all my dresses, gems, and pearls...",
  ui_story_5086_50861100_108_dialog_content = "Would you stay here with me forever?",
  ui_story_5086_50861100_109_dialog_content = "...",
  ui_story_5086_50861100_110_dialog_content = "I don't want your treasures at all, Maya.",
  ui_story_5086_50861100_111_dialog_content = "I just want you to smile.",
  ui_story_5086_50861100_112_dialog_content = "And that's the truth, both here and in the real world.",
  ui_story_5086_50861100_113_dialog_content = "!",
  ui_story_5086_50861100_114_dialog_content = "<color=#e8d9bb>The long and distant chanting begins again.</color>",
  ui_story_5086_50861100_115_dialog_content = "<color=#e8d9bb>The dream-like scene surrounding them turns to mist and gradually fades away, revealing the dimly-lit aquarium once again.</color>",
  ui_story_5086_50861100_116_dialog_content = "We're back... Huh? Why is everyone asleep?",
  ui_story_5086_50861100_117_dialog_content = "Ahhh—What a wonderful nap! Heehee!",
  ui_story_5086_50861100_118_dialog_content = "Welcome back, Maya.",
  ui_story_5086_50861100_119_dialog_content = "I know I said all of that just now, but you don't have to force yourself to smile if you don't feel like it.",
  ui_story_5086_50861100_120_dialog_content = "It wouldn't be right if you did.",
  ui_story_5086_50861100_121_dialog_content = "...",
  ui_story_5086_50861100_122_dialog_content = "Ever since that guest disappeared, you haven't smiled once. Not a real smile, anyway.",
  ui_story_5086_50861100_123_dialog_content = "... I just don't know what to do anymore.",
  ui_story_5086_50861100_124_dialog_content = "So you knew exactly who made that person go missing all along.",
  ui_story_5086_50861100_125_dialog_content = "I want people to feel remorse when they do bad things...",
  ui_story_5086_50861100_126_dialog_content = "I sent her into that dream to repent until she's ready to make it up to everyone.",
  ui_story_5086_50861100_127_dialog_content = "I... I just have to try a little harder to preserve her dream!",
  ui_story_5086_50861100_128_dialog_content = "I'm sure she knows what she did was wrong!",
  ui_story_5086_50861100_129_dialog_content = "So please, just give me a little more time...",
  ui_story_5086_50861100_130_dialog_content = "You can't erase other people's mistakes, Maya.",
  ui_story_5086_50861100_131_dialog_content = "And we can't live in a dream forever, either.",
  ui_story_5086_50861100_132_dialog_content = "And in your heart, you know that already. It's why the aquarium returned to this state again.",
  ui_story_5086_50861100_133_dialog_content = "You still haven't mastered the ability to control dreams, which is why they turn scary whenever you force yourself to do it.",
  ui_story_5086_50861100_134_dialog_content = "I don't understand... Why won't she feel sorry for her actions? Why does she insist on making us hurt each other?",
  ui_story_5086_50861100_135_dialog_content = "Maybe it's because not everyone is as strong as you, Maya.",
  ui_story_5086_50861100_136_dialog_content = "Is this me... being strong?",
  ui_story_5086_50861100_137_dialog_content = "Even though I'm crying?",
  ui_story_5086_50861100_138_dialog_content = "That's not it at all.",
  ui_story_5086_50861100_139_dialog_content = "It's okay to cry and get angry when we feel pain or hopelessness. It's a perfectly normal reaction.",
  ui_story_5086_50861100_140_dialog_content = "Strong people don't become weak just because they cry.",
  ui_story_5086_50861100_141_dialog_content = "I don't understand.",
  ui_story_5086_50861100_142_dialog_content = "Hmm, then let me put it another way.",
  ui_story_5086_50861100_143_dialog_content = "If you ever find yourself in serious trouble...",
  ui_story_5086_50861100_144_dialog_content = "For example, imagine if the aquarium started getting fewer visitors and was in danger of closing.",
  ui_story_5086_50861100_145_dialog_content = "What the first thing you'll do?",
  ui_story_5086_50861100_146_dialog_content = "Closing...? No way! I would go out and find more guests if that ever happened!",
  ui_story_5086_50861100_147_dialog_content = "So what would you do if no one in Harbor City was willing to visit the aquarium?",
  ui_story_5086_50861100_148_dialog_content = "Go someplace far, far away! I'll go outside of Harbor City, or the other side of the sea, or even the other side of the sky!",
  ui_story_5086_50861100_149_dialog_content = "I would just keep looking! I'm sure I'll find someone who wants to visit us eventually!",
  ui_story_5086_50861100_150_dialog_content = "And if you fail?",
  ui_story_5086_50861100_151_dialog_content = "If at first you don't succeed, try and try again!",
  ui_story_5086_50861100_152_dialog_content = "And you wouldn't feel discouraged about that?",
  ui_story_5086_50861100_153_dialog_content = "I'll feel bad, but there will always be tomorrow! Besides, it's not like I'll remember anything!",
  ui_story_5086_50861100_154_dialog_content = "But I know that as long as I keep trying my hardest, I'll eventually succeed!",
  ui_story_5086_50861100_155_dialog_content = "Because that's just how the world works!",
  ui_story_5086_50861100_156_dialog_content = "And that's what makes me strong.",
  ui_story_5086_50861100_157_dialog_content = "Most people in the world don't dare to hope the way you do, Maya.",
  ui_story_5086_50861100_158_dialog_content = "That's because they live in a bubble known as reality.",
  ui_story_5086_50861100_159_dialog_content = "In that bubble, hard work isn't guaranteed to pay off, and miracles don't just happen because people believe in them.",
  ui_story_5086_50861100_160_dialog_content = "Some people never get to see a happy ending to their stories. They just suffer hardship after painful hardship.",
  ui_story_5086_50861100_161_dialog_content = "It would be such a heavy and difficult burden to bear, and there's no telling how long you would have to carry it.",
  ui_story_5086_50861100_162_dialog_content = "Sometimes, they don't even know if these bitter stories will ever come to an end.",
  ui_story_5086_50861100_163_dialog_content = "Most people would buckle under the weight eventually, with no way of getting up and moving again.",
  ui_story_5086_50861100_164_dialog_content = "But I don't like that...",
  ui_story_5086_50861100_165_dialog_content = "Nobody does, Maya.",
  ui_story_5086_50861100_166_dialog_content = "So, those who find it impossible to endure any longer impose it on others.",
  ui_story_5086_50861100_167_dialog_content = "Huh...?",
  ui_story_5086_50861100_168_dialog_content = "As long as someone else struggles for him, he can suffer a little longer. As long as someone else gets hurt in his place, he'll keep pushing forward.",
  ui_story_5086_50861100_169_dialog_content = "As long as there are people willing to share his burden, he might live to see a happy ending to his story someday.",
  ui_story_5086_50861100_170_dialog_content = "...",
  ui_story_5086_50861100_171_dialog_content = "That person... He was like that, too.",
  ui_story_5086_50861100_172_dialog_content = "He pushed his pain onto other people just to keep going.",
  ui_story_5086_50861100_173_dialog_content = "She did a bad thing, something she should have never done.",
  ui_story_5086_50861100_174_dialog_content = "Well, I understand your desire to make wrongdoers repent.",
  ui_story_5086_50861100_175_dialog_content = "But those who commit evil are weak at heart, so they cannot bear the weight of their mistakes on their own.",
  ui_story_5086_50861100_176_dialog_content = "Even if it's saddening, we can only face them and seek justice.",
  ui_story_5086_50861100_177_dialog_content = "I'm sorry, Maya... But it's unattainable via dreams alone.",
  ui_story_5086_50861100_178_dialog_content = "Good people deserve to be rewarded, and bad people deserve to be punished. Even I know that...",
  ui_story_5086_50861100_179_dialog_content = "And that's the only way a story can reach its end.",
  ui_story_5086_50861100_180_dialog_content = "I've witnessed numerous sad dreams. Thank you for allowing me to witness such precious dreams.",
  ui_story_5086_50861100_181_dialog_content = "Don't worry, Maya... I'll stay by your side, even though I can't do much to help.",
  ui_story_5086_50861100_182_dialog_content = "No, this is already more than enough.",
  ui_story_5086_50861100_183_dialog_content = "I won't give up. I'll resolve things in reality so that everyone will smile again!",
  ui_story_5086_50861100_184_dialog_content = "I'm sorry, Ancestor. Please help me send everyone back!",
  ui_story_5086_50861100_185_dialog_content = "<color=#e8d9bb>In the next moment, the darkened aquarium disappears like a popped bubble.</color>",
  ui_story_5086_50861100_186_dialog_content = "<color=#e8d9bb>Vaguely, I hear a voice somewhere nearby...</color>",
  ui_story_5086_50861100_187_dialog_content = "Descendant of the Caelestites, I beseech you to protect my blood.",
  ui_story_5086_50861100_188_dialog_content = "She is a rarity, a person of pure and untainted sincerity.",
  ui_story_5086_50861100_189_dialog_content = "<color=#e8d9bb>And so the distorted illusion finally came to an end.</color>",
  ui_story_5086_50861201_1_dialog_content = "Urgh... When did I fall asleep... Huh? Everything's back to normal?",
  ui_story_5086_50861201_2_dialog_content = "The power is on, and the aquarium is totally fine.",
  ui_story_5086_50861201_3_dialog_content = "Even the door is intact, and nothing is flooded.",
  ui_story_5086_50861201_4_dialog_content = "Was it all just a dream?",
  ui_story_5086_50861201_5_dialog_content = "Ah! Hey! Are you alright?!",
  ui_story_5086_50861201_6_dialog_content = "Nngh... Wh-What's going on...?",
  ui_story_5086_50861201_7_dialog_content = "I thought you went missing! Thank goodness you only have some light injuries...",
  ui_story_5086_50861201_8_dialog_content = "What the heck did we just experience...?",
  ui_story_5086_50861201_9_dialog_content = "It was all an illusion, but thanks to Maya, no one else got hurt.",
  ui_story_5086_50861201_10_dialog_content = "I... I can't remember anymore.",
  ui_story_5086_50861201_11_dialog_content = "I'm sure Maya was puzzled by those cases and worked hard to solve them.",
  ui_story_5086_50861201_12_dialog_content = "So, when she finally captured the culprit's malice, she recklessly cast that illusion.",
  ui_story_5086_50861201_13_dialog_content = "Maya was afraid someone else would get hurt, so she desperately used an ability that may even bring harm to herself, and that is why the nightmare remained only a nightmare.",
  ui_story_5086_50861201_14_dialog_content = "Did I manage to make up for some of that person's mistakes?",
  ui_story_5086_50861201_15_dialog_content = "... Yes.",
  ui_story_5086_50861201_16_dialog_content = "Where's Miss Stellandine?",
  ui_story_5086_50861201_17_dialog_content = "How come she's the only one not here?",
  ui_story_5086_50861201_18_dialog_content = "Did something happen? There was a swarm of Eclipsites back there...",
  ui_story_5086_50861201_19_dialog_content = "That isn't necessary.",
  ui_story_5086_50861201_20_dialog_content = "I'm afraid she's the only one among us who doesn't have to worry about Eclipsites at all.",
  ui_story_5086_50861201_21_dialog_content = "Minos, did you know right from the start?",
  ui_story_5086_50861201_22_dialog_content = "You think too highly of me. I too gradually confirmed my suspicions via certain characteristics.",
  ui_story_5086_50861201_23_dialog_content = "What are you talking about?",
  ui_story_5086_50861201_24_dialog_content = "I'm sure all of you've heard the fairy tale about the mermaid princess.",
  ui_story_5086_50861201_25_dialog_content = "Fairy tales may be a fantasy, they still have a side that's rooted in reality—Metaphors or lessons.",
  ui_story_5086_50861201_26_dialog_content = "One of the ways to interpret that fairy tale is that it displays the form and habits of a type of marine lifeform.",
  ui_story_5086_50861201_27_dialog_content = "A creature that takes the form of a beautiful Aurorian uses its voice and appearance to attract sailors or visitors.",
  ui_story_5086_50861201_28_dialog_content = "Once its target has been enticed...",
  ui_story_5086_50861201_29_dialog_content = "It pulls the target into the ocean's depths, turning them into its food.",
  ui_story_5086_50861201_30_dialog_content = "So, the mermaid princess is nothing more than a monster that hunts with \"desire\" as its bait.",
  ui_story_5086_50861201_31_dialog_content = "Don't tell me...",
  ui_story_5086_50861201_32_dialog_content = "So all the disappearances were caused by the creature that infiltrated our group?",
  ui_story_5086_50861201_33_dialog_content = "No matter how it changes itself, a monster will always...",
  ui_story_5086_50861201_34_dialog_content = "Shut up!",
  ui_story_5086_50861201_35_dialog_content = "Eclipsites!",
  ui_story_5086_50861201_36_dialog_content = "Shut up! Shut up! Shut up!!!",
  ui_story_5086_50861201_37_dialog_content = "No, that voice... Miss Stellandine?!",
  ui_story_5086_50861201_38_dialog_content = "?!",
  ui_story_5086_50861201_39_dialog_content = "Monster? Creature?!",
  ui_story_5086_50861201_40_dialog_content = "If you're hungry, you eat! It's the same for everyone!",
  ui_story_5086_50861201_41_dialog_content = "No excuse in the world will change the fact that you too rely on the flesh and blood of other living beings to survive!",
  ui_story_5086_50861201_42_dialog_content = "It's just our food differs...",
  ui_story_5086_50861201_43_dialog_content = "Then why have you held back until now?",
  ui_story_5086_50861201_44_dialog_content = "!",
  ui_story_5086_50861201_45_dialog_content = "Even though you were fighting in an illusion, it was still worth studying.",
  ui_story_5086_50861201_46_dialog_content = "You're abnormally weak when compared to others of your kind.",
  ui_story_5086_50861201_47_dialog_content = "It's almost as if... You haven't fed in a very long time.",
  ui_story_5086_50861201_48_dialog_content = "What? Did you really think eating enough Aurorians would allow you to live like one?",
  ui_story_5086_50861201_49_dialog_content = "I told you to shut up!",
  ui_story_5086_50861201_50_dialog_content = "As I understand it, creatures like you can read and learn from the memories of Aurorians that you've devoured.",
  ui_story_5086_50861201_51_dialog_content = "Yet you lack a comprehensive processing system. So, the more you devour, the more chaotic the memories get.",
  ui_story_5086_50861201_52_dialog_content = "You should have never lived ashore, but Stellandine has existed for a long time.",
  ui_story_5086_50861201_53_dialog_content = "No, I should say you've been \"stuck\" for far too long.",
  ui_story_5086_50861201_54_dialog_content = "Not only did you leave the ocean and live like an Aurorian, but you've been refusing to feed for a long time.",
  ui_story_5086_50861201_55_dialog_content = "I really want to know. Why did you do it?",
  ui_story_5086_50861201_56_dialog_content = "I-I want...",
  ui_story_5086_50861201_57_dialog_content = "I see.",
  ui_story_5086_50861201_58_dialog_content = "You've forgotten.",
  ui_story_5086_50861201_59_dialog_content = "I have no other questions. In the end, you're still a pitiful Eclipsite.",
  ui_story_5086_50861201_60_dialog_content = "Why you...!",
  ui_story_5086_50861201_61_dialog_content = "Miss Stellandine...",
  ui_story_5086_50861201_62_dialog_content = "You've done many bad and unforgivable things!",
  ui_story_5086_50861201_63_dialog_content = "But... I know you did sincerely desire to become an Aurorian... That's why I never sensed any malice.",
  ui_story_5086_50861201_64_dialog_content = "If you're still willing to change, then I'm willing to seek atonement with you...",
  ui_story_5086_50861201_65_dialog_content = "Miss Maya, she's an Eclipsite.",
  ui_story_5086_50861201_66_dialog_content = "So long as that remains a fact, we will always be enemies.",
  ui_story_5086_50861201_67_dialog_content = "I'm not trying to defend her or anything... But is Miss Stellandine really gone for good?",
  ui_story_5086_50861201_68_dialog_content = "... That's enough.",
  ui_story_5086_50861201_69_dialog_content = "Miss Stellandine?",
  ui_story_5086_50861201_70_dialog_content = "Oh, Maya...",
  ui_story_5086_50861201_71_dialog_content = "What a huge fool!!",
  ui_story_5086_50861201_72_dialog_content = "... Huh?",
  ui_story_5086_50861201_73_dialog_content = "That's it! That's the expression that garners everyone's affection.",
  ui_story_5086_50861201_74_dialog_content = "\"It's so sad that I can't remember anything, but I know everyone will like me if I do my best in life!\"",
  ui_story_5086_50861201_75_dialog_content = "I'm sure you enjoy it tremendously, right? You must be so pleased with yourself right now!",
  ui_story_5086_50861201_76_dialog_content = "My pitiful yet adorable little Maya... But what was the use? In all your life, not once have you done anything meaningful—",
  ui_story_5086_50861201_77_dialog_content = "But why are you the only one who enjoys everyone's love?!!",
  ui_story_5086_50861201_78_dialog_content = "No, Miss Stellandine... Please... Don't say things like that...",
  ui_story_5086_50861201_79_dialog_content = "That was the only reason I was so kind to you! So that the sting of betrayal would hurt even more!",
  ui_story_5086_50861201_80_dialog_content = "You silly girl! Did you really believe a monster would have Aurorian emotions?! Hahaha! You really fell for it, huh?",
  ui_story_5086_50861201_81_dialog_content = "But Miss Stellandine, I can tell that you're still crying on the inside...",
  ui_story_5086_50861201_82_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5086_50861201_83_dialog_content = "<color=#e8d9bb>A whale doll suddenly slams against Stellandine.</color>",
  ui_story_5086_50861201_84_dialog_content = "Miss Moya is a much better person than you'll ever be!",
  ui_story_5086_50861201_85_dialog_content = "She tells us stories and works hard for the aquarium...",
  ui_story_5086_50861201_86_dialog_content = "Even though she barely remembers anything, she always finds me near the whales whenever I sneak out!",
  ui_story_5086_50861201_87_dialog_content = "But you? You never bothered to remember any of our names!",
  ui_story_5086_50861201_88_dialog_content = "That's right, Maya treats everyone sincerely! You shouldn't have disappointed her, Miss Stellandine.",
  ui_story_5086_50861201_89_dialog_content = "Receive your retribution! Monster!",
  ui_story_5086_50861201_90_dialog_content = "<color=#e8d9bb>Smack! Smack! Smack!</color>",
  ui_story_5086_50861201_91_dialog_content = "<color=#e8d9bb>Dolls, keys, and even stones from inside the aquarium pools... The visitors begin pelting Stellandine with any objects they can find.</color>",
  ui_story_5086_50861201_92_dialog_content = "My, what a touching scene...",
  ui_story_5086_50861201_93_dialog_content = "Then you can all die together!!",
  ui_story_5086_50861202_1_dialog_content = "It's over, Miss Stellandine. Both your life and your desires.",
  ui_story_5086_50861202_2_dialog_content = "Can I... go to her?",
  ui_story_5086_50861202_3_dialog_content = "That's not advisable, Miss Maya.",
  ui_story_5086_50861202_4_dialog_content = "Go ahead, Maya.",
  ui_story_5086_50861202_5_dialog_content = "Thanks!",
  ui_story_5086_50861202_6_dialog_content = "This is unwise.",
  ui_story_5086_50861202_7_dialog_content = "Yet emotions sometimes clash with reason, Minos.",
  ui_story_5086_50861202_8_dialog_content = "...",
  ui_story_5086_50861202_9_dialog_content = "That's true. Go on, Maya!",
  ui_story_5086_50861202_10_dialog_content = "I've been constantly emphasizing our stance against the Eclipsites...",
  ui_story_5086_50861202_11_dialog_content = "I'm aware, Minos.",
  ui_story_5086_50861202_12_dialog_content = "Miss Stellandine's crimes are unforgivable, and so we punished her.",
  ui_story_5086_50861202_13_dialog_content = "But to Maya, she's still someone important who once took care of her.",
  ui_story_5086_50861202_14_dialog_content = "Even if she defeated Miss Stellandine herself... She still cannot let go of those emotions.",
  ui_story_5086_50861202_15_dialog_content = "When it comes to us and the Eclipsites, we have no choice but to see things in black and white.",
  ui_story_5086_50861202_16_dialog_content = "If Miss Maya wishes to remain in Harbor City, these experiences will only taint her life here.",
  ui_story_5086_50861202_17_dialog_content = "... Unless the \"stain\" is converted into \"pain.\"",
  ui_story_5086_50861202_18_dialog_content = "Which would make her out to be an innocent victim who had been deceived all along.",
  ui_story_5086_50861202_19_dialog_content = "Wait... Is that why you and Miss Stellandine just—",
  ui_story_5086_50861202_20_dialog_content = "Shhh.",
  ui_story_5086_50861202_21_dialog_content = "No matter how metaphorical they are, fairy tales will always be popular among children.",
  ui_story_5086_50861202_22_dialog_content = "So long as the righteous triumph and the wicked suffer defeat, it should more than suffice as a happy ending.",
  ui_story_5086_50861202_23_dialog_content = "Overthinking will only rob you of that pure joy.",
  ui_story_5086_50861202_24_dialog_content = "...",
  ui_story_5086_50861202_25_dialog_content = "Miss Stellandine...",
  ui_story_5086_50861202_26_dialog_content = "I'm so sorry. I had no idea.",
  ui_story_5086_50861202_27_dialog_content = "It doesn't matter if it was your desire, pain, or something you've been constantly enduring...",
  ui_story_5086_50861202_28_dialog_content = "If only I had noticed it sooner, maybe I could've helped...",
  ui_story_5086_50861202_29_dialog_content = "You're such a fool...",
  ui_story_5086_50861202_30_dialog_content = "Don't you hate me after hearing all of that?",
  ui_story_5086_50861202_31_dialog_content = "\"Miss Stellandine gave me a home in her aquarium.\"",
  ui_story_5086_50861202_32_dialog_content = "I will never, ever forget!",
  ui_story_5086_50861202_33_dialog_content = "I'm very forgetful, so I refuse to just let go of anyone!",
  ui_story_5086_50861202_34_dialog_content = "I cannot even remember how many Aurorians I've eaten.",
  ui_story_5086_50861202_35_dialog_content = "I will help you atone.",
  ui_story_5086_50861202_36_dialog_content = "I killed them! It's none of your business... How will you even make up for the lost lives?",
  ui_story_5086_50861202_37_dialog_content = "I cannot bring back the innocents who have passed away, but I intend to help everyone overcome their pain!",
  ui_story_5086_50861202_38_dialog_content = "May it be prostrating to them or making amends for the pain they suffer, I will work hard to that end!",
  ui_story_5086_50861202_39_dialog_content = "If you're starving right now, you can have some of my flesh, Miss Stellandine!",
  ui_story_5086_50861202_40_dialog_content = "I will forget the pain, and I will heal fast too!",
  ui_story_5086_50861202_41_dialog_content = "I only wish to cry my heart out for, you, the one who once took care of me, and I'll make it up to everyone in the future.",
  ui_story_5086_50861202_42_dialog_content = "So... Don't push me away...",
  ui_story_5086_50861202_43_dialog_content = "Shush... Don't say things like that, I'm already...",
  ui_story_5086_50861202_44_dialog_content = "You have nothing to repay, my child... It is I who has a debt to repay...",
  ui_story_5086_50861202_45_dialog_content = "So, people really do speak sincerely when it's their last, huh?",
  ui_story_5086_50861202_46_dialog_content = "You're... very much like him.",
  ui_story_5086_50861202_47_dialog_content = "Imposing... Admirable...",
  ui_story_5086_50861202_48_dialog_content = "...",
  ui_story_5086_50861202_49_dialog_content = "He ignored my singing and focused solely on fighting the storm.",
  ui_story_5086_50861202_50_dialog_content = "He looked absolutely handsome as he desperately steadied the ship amid the raging storm.",
  ui_story_5086_50861202_51_dialog_content = "I wanted to wait for his return, but he never did... I went ashore in search of him, but I couldn't find him...",
  ui_story_5086_50861202_52_dialog_content = "I ate many Aurorians, and many new faces appeared in my memories.",
  ui_story_5086_50861202_53_dialog_content = "And as time passed... I could no longer tell which face belonged to him.",
  ui_story_5086_50861202_54_dialog_content = "I seemed to be still waiting, yet all my waiting...",
  ui_story_5086_50861202_55_dialog_content = "Was nothing more than a reverie.",
  ui_story_5086_50861202_56_dialog_content = "I-I will find him for you.",
  ui_story_5086_50861202_57_dialog_content = "No... You don't have to.",
  ui_story_5086_50861202_58_dialog_content = "Because I picked up a little girl right outside the aquarium, a silly and naive little girl who never doubted anyone...",
  ui_story_5086_50861202_59_dialog_content = "A noisy little girl who could never keep quiet. And I couldn't help but worry...",
  ui_story_5086_50861202_60_dialog_content = "What would she do without me?",
  ui_story_5086_50861202_61_dialog_content = "I thought about it... I thought about being Stellandine and staying with my Maya...",
  ui_story_5086_50861202_62_dialog_content = "But I was so hungry... I was really... starving...",
  ui_story_5086_50861202_63_dialog_content = "...",
  ui_story_5086_50861202_64_dialog_content = "I knew that it would break my Maya's heart... But... I'm just a monster that couldn't overcome its nature...",
  ui_story_5086_50861202_65_dialog_content = "The only way for me to survive was to eat Aurorians... And what came out of that? Hah!",
  ui_story_5086_50861202_66_dialog_content = "In the end... I lost everything...",
  ui_story_5086_50861202_67_dialog_content = "I really am a pitiful monster...",
  ui_story_5086_50861202_68_dialog_content = "If only... I had the heart of an Aurorian... Then could I have...",
  ui_story_5086_50861202_69_dialog_content = "<color=#e8d9bb>Splash—</color>",
  ui_story_5086_50861202_70_dialog_content = "?",
  ui_story_5086_50861202_71_dialog_content = "This place... Why? Wasn't I...",
  ui_story_5086_50861202_72_dialog_content = "<color=#e8d9bb>Rumble—!</color>",
  ui_story_5086_50861202_73_dialog_content = "A storm?! It can't be!",
  ui_story_5086_50861202_74_dialog_content = "Don't even think about overturning our ship, storm!",
  ui_story_5086_50861202_75_dialog_content = "Brothers! Let's show Poseidon how courageous we are!",
  ui_story_5086_50861202_76_dialog_content = "Let's cross this storm! Heave! Ho!",
  ui_story_5086_50861202_77_dialog_content = "Hey! Get down there and secure that ship!",
  ui_story_5086_50861202_78_dialog_content = "And don't do anything else unless I give the order.",
  ui_story_5086_50861202_79_dialog_content = "Roar!",
  ui_story_5086_50861202_80_dialog_content = "Huh? The ship suddenly steadied itself... Perfect! Let's rush out now!",
  ui_story_5086_50861202_81_dialog_content = "<color=#e8d9bb>The ship gradually vanishes into the horizon amid the shrinking storm.</color>",
  ui_story_5086_50861202_82_dialog_content = "...",
  ui_story_5086_50861202_83_dialog_content = "Aren't you going to go after them?",
  ui_story_5086_50861202_84_dialog_content = "No.",
  ui_story_5086_50861202_85_dialog_content = "This way, I won't make the same mistakes again, and I won't hurt that little girl again.",
  ui_story_5086_50861202_86_dialog_content = "I can extract that sailor's appearance from your memories.",
  ui_story_5086_50861202_87_dialog_content = "At least at the end, you can...",
  ui_story_5086_50861202_88_dialog_content = "This is a dream that the child created for me, right?",
  ui_story_5086_50861202_89_dialog_content = "... Yes.",
  ui_story_5086_50861202_90_dialog_content = "Am I dying?",
  ui_story_5086_50861202_91_dialog_content = "Yes.",
  ui_story_5086_50861202_92_dialog_content = "Good.",
  ui_story_5086_50861202_93_dialog_content = "A monster like me should die with regrets.",
  ui_story_5086_50861202_94_dialog_content = "I should atone for my sins by suffering eternal pain.",
  ui_story_5086_50861202_95_dialog_content = "Can she see me?",
  ui_story_5086_50861202_96_dialog_content = "... No.",
  ui_story_5086_50861202_97_dialog_content = "Then tell her it was a sweet dream.",
  ui_story_5086_50861202_98_dialog_content = "So then...",
  ui_story_5086_50861202_99_dialog_content = "<color=#e8d9bb>Splash.</color>",
  ui_story_5086_50861202_100_dialog_content = "<color=#e8d9bb>My words are met with a sudden force pushing me away and a light splash on the ocean.</color>",
  ui_story_5086_50861202_101_dialog_content = "<color=#e8d9bb>Stellandine sinks into the water and her figure gradually blurs as the link is cut.</color>",
  ui_story_5086_50861202_102_dialog_content = "<color=#e8d9bb>She was born of the ocean, and now, she seems to have returned to its embrace. Motionlessly... just sinking, and sinking to the bottom.</color>",
  ui_story_5086_50861202_103_dialog_content = "Stellandine!",
  ui_story_5086_50861202_104_dialog_content = "Hmm-hmm.",
  ui_story_5086_50861202_105_dialog_content = "<color=#e8d9bb>Ignoring my calls and obstruction, the monster starts to sing while sinking into the abyss.</color>",
  ui_story_5086_50861202_106_dialog_content = "<color=#e8d9bb>A siren's song could deceive the mind and turn all who hear it into prey.</color>",
  ui_story_5086_50861202_107_dialog_content = "<color=#e8d9bb>But this melody harmed no one.</color>",
  ui_story_5086_50861202_108_dialog_content = "<color=#e8d9bb>It's just... A sad and tender blessing from the icy depths of the ocean.</color>",
  ui_story_5086_50861202_109_dialog_content = "My... poor... adorable... little Maya...",
  ui_story_5086_50861202_110_dialog_content = "May you... live happily... with those you love.",
  ui_story_5086_50861202_111_dialog_content = "<color=#e8d9bb>Stellandine's body starts to fade in the aquarium's lobby.</color>",
  ui_story_5086_50861202_112_dialog_content = "It is true that I can sense the good and evil in a person.",
  ui_story_5086_50861202_113_dialog_content = "So even if I'm forgetful, I can't be deceived that easily.",
  ui_story_5086_50861202_114_dialog_content = "Miss Stellandine was an Eclipsite, but since the day we met, and even just now...",
  ui_story_5086_50861202_115_dialog_content = "She never had even the slightest malice toward me.",
  ui_story_5086_50861202_116_dialog_content = "So, the very least I can do is give her a sweet dream, right?",
  ui_story_5086_50861202_117_dialog_content = "Yes.",
  ui_story_5086_50861202_118_dialog_content = "In the past, she couldn't let go of her desire to survive, nor could she give up her wishful thoughts.",
  ui_story_5086_50861202_119_dialog_content = "But when she let go of it all and lost everything, she was still willing to give her sincere blessings...",
  ui_story_5086_50861202_120_dialog_content = "In my opinion, she repented, and so she was no longer just a monster.",
  ui_story_5086_50861202_121_dialog_content = "She desired the heart of an Aurorian, and now, at the moment of her death, she can gradually repay it all.",
  ui_story_5086_50861202_122_dialog_content = "<color=#e8d9bb>In the silent depths of the ocean dream.</color>",
  ui_story_5086_50861202_123_dialog_content = "<color=#e8d9bb>Suddenly, a ray of dazzling light appears before Stellandine's sinking figure.</color>",
  ui_story_5086_50861202_124_dialog_content = "<color=#e8d9bb>A sailor reaches out to her from within the light, his handsome face clearly reflected in her eyes.</color>",
  ui_story_5086_50861202_125_dialog_content = "Come with me.",
  ui_story_5086_50861202_126_dialog_content = "... Okay.",
  ui_story_5086_50861202_127_dialog_content = "<color=#e8d9bb>Stellandine smiles before completely fading away.</color>",
  ui_story_5086_50861202_128_dialog_content = "Thank you, PlayerName.",
  ui_story_5086_50861202_129_dialog_content = "Um... I don't know how to say this, but thank you for everything.",
  ui_story_5086_50861202_130_dialog_content = "Not at all. I merely helped Miss Stellandine recall the sailor's face.",
  ui_story_5086_50861202_131_dialog_content = "Actually, it's you who gave Miss Stellandine salvation, Maya.",
  ui_story_5086_50861202_132_dialog_content = "Because love is eternal...",
  ui_story_5086_50861202_133_dialog_content = "Oh, right! My notes!",
  ui_story_5086_50861202_134_dialog_content = "I must write it down... Ah!",
  ui_story_5086_50861202_135_dialog_content = "<color=#e8d9bb>As Maya fumbles for her notes, a card falls out behind its cover.</color>",
  ui_story_5086_50861202_136_dialog_content = "Is that... Jeno's Origin Deck?!",
  ui_story_5086_50861300_1_dialog_content = "<color=#e8d9bb>After the circus incident—</color>",
  ui_story_5086_50861300_2_dialog_content = "Jeno...",
  ui_story_5086_50861300_3_dialog_content = "There won't be any more performances.",
  ui_story_5086_50861300_4_dialog_content = "I knew you could read minds, Jeno!",
  ui_story_5086_50861300_5_dialog_content = "No, it's because you would ask if someone sought your help.",
  ui_story_5086_50861300_6_dialog_content = "Let's leave Harbor City once the Emerald is fixed.",
  ui_story_5086_50861300_7_dialog_content = "Huh? But so many are looking forward to the performance, and... Elvis...",
  ui_story_5086_50861300_8_dialog_content = "Elvis is the reason we must leave.",
  ui_story_5086_50861300_9_dialog_content = "Come with me, Maya.",
  ui_story_5086_50861300_10_dialog_content = "My departure is set in stone, but you're new, so I'm not going to force you.",
  ui_story_5086_50861300_11_dialog_content = "So are you coming with us? Or will you stay here instead?",
  ui_story_5086_50861300_12_dialog_content = "If I go with you, can I help you and Elvis?",
  ui_story_5086_50861300_13_dialog_content = "It seems difficult to me because you cannot control your power.",
  ui_story_5086_50861300_14_dialog_content = "I see...",
  ui_story_5086_50861300_15_dialog_content = "I understand! I'll just stay here then!",
  ui_story_5086_50861300_16_dialog_content = "Elvis has always looked after me, and it's time I helped him look after Harbor City.",
  ui_story_5086_50861300_17_dialog_content = "I may not be the most reliable... But I promise to do my best to help everyone!",
  ui_story_5086_50861300_18_dialog_content = "Now that Elvis is no longer the City Lord, he can't send anyone to protect you anymore.",
  ui_story_5086_50861300_19_dialog_content = "You'll have to live independently like you used to.",
  ui_story_5086_50861300_20_dialog_content = "I'm a hard worker, so I won't starve! Don't worry about me! I have heaps of work experience! Though I seem to have forgotten it all...",
  ui_story_5086_50861300_21_dialog_content = "But...",
  ui_story_5086_50861300_22_dialog_content = "Miss Stellandine from the aquarium was really kind. I made a lot of money there!",
  ui_story_5086_50861300_23_dialog_content = "You should focus on more important matters, Jeno!",
  ui_story_5086_50861300_24_dialog_content = "Then I have a favor to ask of you.",
  ui_story_5086_50861300_25_dialog_content = "I don't mind even a hundred favors!",
  ui_story_5086_50861300_26_dialog_content = "It's nothing grand. I just need you to pass a message.",
  ui_story_5086_50861300_27_dialog_content = "Well... I'm afraid I'll forget it...",
  ui_story_5086_50861300_28_dialog_content = "That's exactly what makes you so reliable.",
  ui_story_5086_50861300_29_dialog_content = "Live well in the aquarium. We'll come see you someday.",
  ui_story_5086_50861300_30_dialog_content = "So... does that mean Maya was Jeno's messenger, after all?",
  ui_story_5086_50861300_31_dialog_content = "A message?",
  ui_story_5086_50861300_32_dialog_content = "I don't remember anything like that...",
  ui_story_5086_50861300_33_dialog_content = "But I vaguely remember something about taking good care of this card.",
  ui_story_5086_50861300_34_dialog_content = "Have I forgotten something important again?",
  ui_story_5086_50861300_35_dialog_content = "No, I think it's a part of Jeno's trick.",
  ui_story_5086_50861300_36_dialog_content = "Most only notice the water mysteriously vanishing from the cup.",
  ui_story_5086_50861300_37_dialog_content = "But in the eyes of a magician, it's as simple as taking out an empty glass from under the table.",
  ui_story_5086_50861300_38_dialog_content = "I see! The riddle has always been right in front of us! Though no one but I could ever discover it!",
  ui_story_5086_50861300_39_dialog_content = "PlayerName, are you going to pull something out?",
  ui_story_5086_50861300_40_dialog_content = "It's your memories.",
  ui_story_5086_50861300_41_dialog_content = "Oh, but don't worry. Jeno wouldn't just leave the Origin Deck behind.",
  ui_story_5086_50861300_42_dialog_content = "If I use it as my guide, I should be able to locate the message without touching any of your other memories.",
  ui_story_5086_50861300_43_dialog_content = "It's fine.",
  ui_story_5086_50861300_44_dialog_content = "Huh?",
  ui_story_5086_50861300_45_dialog_content = "PlayerName, even though you declined nice clothes, gems, and even pearls...",
  ui_story_5086_50861300_46_dialog_content = "But you're always welcome to enjoy yourself in my dreams, the Ancestor have permitted it!",
  ui_story_5086_50861300_47_dialog_content = "It'd be my honor.",
  ui_story_5086_50861300_48_dialog_content = "Then—",
  ui_story_5086_50861300_49_option_content = "Mindlink!",
  ui_story_5086_50861300_50_dialog_content = "(Focus! Focus on the wave that syncs with the Origin Deck...)",
  ui_story_5086_50861300_51_dialog_content = "(Found it!)",
  ui_story_5086_50861300_52_dialog_content = "You're the only one who could ever get here, so I'll get straight to the point.",
  ui_story_5086_50861300_53_dialog_content = "Elvis is awake.",
  ui_story_5086_50861300_54_dialog_content = "(!)",
  ui_story_5086_50861300_55_dialog_content = "Though it was for just a moment, and he fell asleep right after, it's enough to prove that <color=#FFB400>the woman's </color> treatment method is going in the right direction.",
  ui_story_5086_50861300_56_dialog_content = "Elvis... never considers the big picture. He just charges blindly at the sight of even a glimmer of hope and leaves everyone behind.",
  ui_story_5086_50861300_57_dialog_content = "He's an absolutely selfish yet righteous man.",
  ui_story_5086_50861300_58_dialog_content = "But I have no right to speak ill of him. Because no matter what he does, I find it impossible to hate him.",
  ui_story_5086_50861300_59_dialog_content = "So, my only option is to be his accomplice.",
  ui_story_5086_50861300_60_dialog_content = "I'll be taking him to the next step in his treatment.",
  ui_story_5086_50861300_61_dialog_content = "Caelestite, I may need your help ensuring Elvis's consciousness remains intact.",
  ui_story_5086_50861300_62_dialog_content = "That's why I made Maya convey this information to you.",
  ui_story_5086_50861300_63_dialog_content = "Please keep it a secret from anyone connected to Lumopolis, including your companions.",
  ui_story_5086_50861300_64_dialog_content = "I'll find a way to contact you when the time is right.",
  ui_story_5086_50861300_65_dialog_content = "Is that all?",
  ui_story_5086_50861300_66_dialog_content = "Hmm... No, there's one more thing.",
  ui_story_5086_50861300_67_dialog_content = "I'm not a great leader, so I thought about leaving the circus behind. It's a shame that the Emerald is so full of stubborn and inflexible people.",
  ui_story_5086_50861300_68_dialog_content = "They insist on following me, and if I add Elvis to the equation... Well, the conclusion is we're leaving Maya on her own in Harbor City.",
  ui_story_5086_50861300_69_dialog_content = "I heard Elvis promised her father that he would always be there for her.",
  ui_story_5086_50861300_70_dialog_content = "So, I have no choice but to ask you to help us with that.",
  ui_story_5086_50861300_71_dialog_content = "Don't worry, I'll be fine!",
  ui_story_5086_50861300_72_dialog_content = "Maya... Are you really not coming with us?",
  ui_story_5086_50861300_73_dialog_content = "Boo-hoo... I'm gonna miss you...",
  ui_story_5086_50861300_74_dialog_content = "(Let's stop here.)",
  ui_story_5086_50861300_75_dialog_content = "Well?",
  ui_story_5086_50861300_76_dialog_content = "Did you find what you were looking for?",
  ui_story_5086_50861300_77_dialog_content = "I did! Thank you, Maya. You really did me a solid there.",
  ui_story_5086_50861300_78_dialog_content = "Awesome!",
  ui_story_5086_50861300_79_dialog_content = "Anyway... Now that Miss Stellandine is gone...",
  ui_story_5086_50861300_80_dialog_content = "Would you like to come with me?",
  ui_story_5086_50861300_81_dialog_content = "Though I can't give you the best, there are many empty rooms on the Colossus...",
  ui_story_5086_50861300_82_dialog_content = "I really like you, PlayerName!",
  ui_story_5086_50861300_83_dialog_content = "Huh?! Where did that come from...",
  ui_story_5086_50861300_84_dialog_content = "Heehee! But I also like Elvis, the sea, and Harbor City.",
  ui_story_5086_50861300_85_dialog_content = "And even if I must keep it a secret...",
  ui_story_5086_50861300_86_dialog_content = "I really like Miss Stellandine too!",
  ui_story_5086_50861300_87_dialog_content = "For that reason, I want to stay and keep this aquarium alive.",
  ui_story_5086_50861300_88_dialog_content = "The aquarium will always be my home.",
  ui_story_5086_50861300_89_dialog_content = "And I will do my best to make up for everything and heal everyone's scars, so that we can all smile again.",
  ui_story_5086_50861300_90_dialog_content = "Fine... If I ever encounter a doctor capable of treating your memory loss, you can be sure I'll bring them to you.",
  ui_story_5086_50861300_91_dialog_content = "Thank you, though you really don't have to worry about it.",
  ui_story_5086_50861300_92_dialog_content = "I'm confident that I'll be able to live a better life.",
  ui_story_5086_50861300_93_dialog_content = "Also, <color=#FFB400>I</color>'ve figured some things out.",
  ui_story_5086_50861300_94_dialog_content = "What is it?",
  ui_story_5086_50861300_95_dialog_content = "Hehe! <color=#FFB400>I</color> recorded it in my notes. I'll let you read it when we meet again.",
  ui_story_5086_50861300_96_dialog_content = "But it's a secret for now!",
  ui_story_5086_50861300_97_dialog_content = "<color=#e8d9bb>The knights of Lumopolis took over the remaining work.</color>",
  ui_story_5086_50861300_98_dialog_content = "<color=#e8d9bb>Those who stepped up were rewarded and left.</color>",
  ui_story_5086_50861300_99_dialog_content = "<color=#e8d9bb>And the exhausted visitors left after giving an account of everything they knew.</color>",
  ui_story_5086_50861300_100_dialog_content = "<color=#e8d9bb>Once the employees left as well, Maya was left all alone in the aquarium at night... And another who was silently making his way back.</color>",
  ui_story_5086_50861300_101_dialog_content = "Hello, Miss Maya.",
  ui_story_5086_50861300_102_dialog_content = "Mr. Minos? What are you doing back here? Did you forget something?",
  ui_story_5086_50861300_103_dialog_content = "I just wanted to confirm something.",
  ui_story_5086_50861300_104_dialog_content = "Huh? What's that supposed to mean?",
  ui_story_5086_50861300_105_dialog_content = "Then let me explain briefly.",
  ui_story_5086_50861300_106_dialog_content = "You told the children a story.",
  ui_story_5086_50861300_107_dialog_content = "It was about a boy and a sea monster in a small town...",
  ui_story_5086_50861300_108_dialog_content = "Did I tell a story like that? It sounds really interesting!",
  ui_story_5086_50861300_109_dialog_content = "Indeed, it was. Miss Maya, you have an absolutely free and vibrant imagination.",
  ui_story_5086_50861300_110_dialog_content = "But I had the pleasure of reading the original story.",
  ui_story_5086_50861300_111_dialog_content = "In the original, once the boy grew up, he went off in search of the town again.",
  ui_story_5086_50861300_112_dialog_content = "But no matter how many beaches and forests he crossed, he could never find his way back there.",
  ui_story_5086_50861300_113_dialog_content = "It turns out the town resides between the cracks of a dream, and it's only projected into reality when someone sees or observes it.",
  ui_story_5086_50861300_114_dialog_content = "The boy and the weeping girl became friends, and he helped the people eliminate the sea monster. Yet, no visitors ever visited the town again.",
  ui_story_5086_50861300_115_dialog_content = "As time passed, the town itself disappeared.",
  ui_story_5086_50861300_116_dialog_content = "If that happened, do you think the cat would regret dragging the boy into all of it?",
  ui_story_5086_50861300_117_dialog_content = "The cat possesses incredible power, and \"her\" thoughts will affect my judgment on certain matters.",
  ui_story_5086_50861300_118_dialog_content = "I... actually don't quite understand your story, Mr. Minos.",
  ui_story_5086_50861300_119_dialog_content = "But the girl who cried alone daily made a friend because of the boy.",
  ui_story_5086_50861300_120_dialog_content = "And the visitors who were drawn there by the legend seemed to have left after enjoying themselves to the fullest.",
  ui_story_5086_50861300_121_dialog_content = "In the end, everyone from the dream returned to where they came from.",
  ui_story_5086_50861300_122_dialog_content = "So perhaps the cat... didn't think anything of it.",
  ui_story_5086_50861300_123_dialog_content = "Although there are some regrets, everyone did their best, and that makes it a happy ending.",
  ui_story_5086_50861300_124_dialog_content = "A good ending... Huh?",
  ui_story_5086_50861300_125_dialog_content = "If I had to say, the cat would definitely want to see the boy again.",
  ui_story_5086_50861300_126_dialog_content = "It would want to take another stroll on the beach together.",
  ui_story_5086_50861300_127_dialog_content = "Watch the waves breaking over the coral reef, flying fish leaping out of the water, and roll in the sand and laugh while watching a bumbling crab stagger back and forth.",
  ui_story_5086_50861300_128_dialog_content = "And at the end of the day, they would curl up under a palm tree and let the sea breeze carry them off to sleep.",
  ui_story_5086_50861300_129_dialog_content = "Is that the cat's current desire?",
  ui_story_5086_50861300_130_dialog_content = "It could have realized that desire by going with the boy.",
  ui_story_5086_50861300_131_dialog_content = "But the cat's home is in the town.",
  ui_story_5086_50861300_132_dialog_content = "So, the cat will wait until the boy returns. After all...",
  ui_story_5086_50861300_133_dialog_content = "Love is eternal.",
  ui_story_5086_50861300_134_dialog_content = "I get it now. Thank you, that's all I wanted to ask.",
  ui_story_5086_50861300_135_dialog_content = "Well, I'm heading back to report the business investigation's outcome to Miss Nina. Farewell!",
  ui_story_5086_50861300_136_dialog_content = "...",
  ui_story_5086_50861300_137_dialog_content = "I hope the cat gets its wish.",
  ui_story_5086_50861300_138_dialog_content = "Don't worry about it.",
